E["npc:felgur-twocuts"] = {t="npc",n="Felgur Twocuts",z="desolace",s="Felgur Twocuts is a blunt orc scout stationed at Ghost Walker Post in Desolace. He coordinates Horde efforts against the regional centaur clans.",h="Felgur Twocuts is a blunt orc scout stationed at Ghost Walker Post in Desolace.",sec={{t="A Gruff Outpost Scout",b="Standing watch amid the bleak expanse of Ghost Walker Post in central Desolace, Felgur Twocuts has little patience for pleasantries. As a forward scout for the Horde, he assesses the threats facing travelers and settlers venturing west through the mountains, particularly the local Kolkar centaur.",sp=0},{t="War on the Centaur",b="Felgur directs Horde champions to cull the local centaur chieftains and collect bounties on the warring tribes who threaten to overrun the region. He is a central contact for anyone seeking to secure the Horde's foothold in Desolace.",sp=0}},faq={{q="Who is Felgur Twocuts?",a="Felgur Twocuts is an orc scout and quest giver stationed at Ghost Walker Post, the Horde's forward encampment in Desolace.",al={"felgur twocuts who","who is felgur"},it="identity"},{q="Where can I find Felgur Twocuts?",a="He is located at Ghost Walker Post, just north of the central road running through Desolace.",al={"felgur twocuts location","where is felgur","where is felgur twocuts"},gp=true},{q="What tasks does Felgur Twocuts give?",a="Felgur enlists Horde adventurers to strike at the local Kolkar centaur, hunt down Khan Dez'hepah, and collect bounties on hostile centaur.",al={"felgur quests","what does felgur want"},gp=true},{q="Why is Felgur so curt with visitors?",a="Desolace is a dangerous and unforgiving wasteland surrounded by hostile centaur clans. Stationed in an isolated post, Felgur has no time for idle chatter and prefers to focus strictly on survival and martial duty.",al={"why is felgur rude","make it quick felgur"}},{q="Whose side is Felgur Twocuts on?",a="Felgur is a proud member of the Horde, stationed far out on the frontier to advance their interests and defend their encampments against regional threats.",al={"felgur twocuts faction","is felgur horde","who does felgur serve"},it="side",add="f5a09a6e"},{q="What does Felgur Twocuts want?",a="Felgur seeks to curb the hostile centaur clans threatening the Horde in Desolace. He enlists capable champions to collect bounties and confront Khan Dez'hepah.",al={"felgur twocuts goal","what is felgur trying to do","what does felgur need"},it="wants",add="8c623583"},{q="Why is Felgur Twocuts stationed here?",a="Felgur is garrisoned at Ghost Walker Post to monitor the local centaur tribes and direct action against threats to the Horde's foothold in Desolace.",al={"why is felgur twocuts at ghost walker post","felgur purpose here","why is felgur out here"},it="why_here",add="a5d710fc"}},ang={["faction:Horde"]="Felgur acts as a vital operations liaison at Ghost Walker Post, helping the Horde push back aggressive centaur tribes in Desolace.",["race:Orc"]="True to standard orcish pragmatism in dangerous borderlands, Felgur values strength, speed, and immediate results over idle conversation."},kw={"centaur bounty","desolace","felgur twocuts","ghost walker post","horde","kolkar","orc"},rel={"subzone:ghost-walker-post","zone:desolace","topic:centaur","quest:1362","topic:horde","zone:barrens"},src={"Felgur Twocuts"}}
E["npc:kreldig-ungor"] = {t="npc",n="Kreldig Ungor",z="desolace",s="Kreldig Ungor is an enterprising dwarven operative representing Reclaimers Inc., stationed high among the crags of Nijel's Point in Desolace. Tasked with managing field operations in the barren wasteland, he hires Alliance adventurers to recover lost cargo and secure valuable local reagents. His salvage and recovery contracts make him a central contact for travelers navigating the hostile region.",h="Kreldig Ungor is an enterprising dwarven operative representing Reclaimers Inc., stationed high among the...",sec={{t="Field Agent in the Wastes",b="Nijel's Point offers the Alliance a rare sanctuary amid the blighted canyons of Desolace, making it an ideal staging ground for commercial opportunists like Kreldig Ungor. Representing Reclaimers Inc., Kreldig has ventured far from the safety of Khaz Modan into a desolate wilderness contested by centaur clans, demons, and the Horde. Where others see ruin and ash, Kreldig sees untapped profit and lost assets ripe for recovery.",sp=0},{t="The Karnitol Contract",b="A primary venture bringing Kreldig to Desolace involves the lost vessel of Karnitol, which wrecked along the treacherous western coast. Karnitol's shipment held prized goods, and Kreldig orchestrates efforts to track down the debris and retrieve the scattered cargo before scavengers or coastal sea giants can claim it all.",sp=0},{t="Harvesting Local Reagents",b="Beyond maritime salvage, Kreldig oversees the procurement of Desolace's strange biological and mineral treasures for Reclaimers Inc. The harsh environment breeds unique fauna and flora, whose parts fetch high prices among alchemists and engineers back in the Eastern Kingdoms. Adventurers willing to brave the wasteland's predators find steady pay beneath Kreldig's ledger.",sp=0}},faq={{q="Who is Kreldig Ungor?",a="Kreldig Ungor is a dwarf operative associated with Reclaimers Inc., based out of the Alliance outpost at Nijel's Point in Desolace. He coordinates salvage missions and specimen gathering across the zone.",al={"kreldig ungor lore","who is kreldig","kreldig ungor"},it="identity"},{q="What is Reclaimers Inc.?",a="Reclaimers Inc. is an entrepreneurial venture focused on salvaging lost cargo, recovering wreckage, and harvesting rare reagents in dangerous frontiers for profit.",al={"reclaimers inc","who are reclaimers inc","reclaimers business"},it="ties"},{q="Where can Kreldig Ungor be found?",a="He is located in the Alliance settlement of Nijel's Point, perched high in the rocky mountains of northeastern Desolace.",al={"kreldig ungor location","where is kreldig","find kreldig ungor"},it="why_here",gp=true},{q="What does Kreldig want with the Karnitol shipwreck?",a="A ship carrying valuable goods belonging to Karnitol wrecked along the Desolace coast. Kreldig employs adventurers to locate the wreck and secure the lost cargo before it is scavenged or destroyed.",al={"karnitol shipwreck","kreldig karnitol","desolace shipwreck"},it="wants"},{q="Why is Kreldig collecting reagents in Desolace?",a="The harsh environment of Desolace fosters rare creatures and unique natural compounds. Kreldig collects these specimens to supply alchemists, artificers, and buyers back in major Alliance cities.",al={"reagents for reclaimers inc","desolace reagents","why collect reagents"},it="motive"},{q="Does Kreldig work for Ironforge or a private enterprise?",a="While he operates from an Alliance outpost and exclusively hires Alliance wanderers, Kreldig represents Reclaimers Inc., a commercial enterprise pursuing salvage and trade rather than official royal military objectives.",al={"kreldig alliance or private","reclaimers inc ironforge"},it="side"},{q="Why is Kreldig Ungor stationed at Nijel's Point?",a="Kreldig Ungor has set up shop high in Nijel's Point to pursue business ventures for Reclaimers Inc. across the rugged expanse of Desolace. From this fortified Alliance refuge, he oversees salvage and procurement operations in relative safety, using it as a base to hire hardy adventurers for ventures down in the perilous wastes.",al={"why is kreldig ungor here","kreldig ungor nijels point","why is kreldig in desolace"},it="why_here",add="ad7684ca"}},ang={["race:Dwarf"]="Kreldig shows off the classic dwarven appetite for rugged frontier exploration and commercial ambition, setting up shop far from the mountain halls.",["faction:Alliance"]="Stationed at Nijel's Point, Kreldig relies entirely on Alliance travelers to keep his salvage contracts moving in an otherwise hostile territory."},kw={"alliance","desolace","dwarf","karnitol shipwreck","kreldig ungor","nijel's point","reclaimers inc","salvage"},rel={"subzone:nijel-s-point","zone:desolace","quest:1453","topic:dwarf"},src={"Kreldig Ungor"}}
E["npc:maurin-bonesplitter"] = {t="npc",n="Maurin Bonesplitter",z="desolace",s="Maurin Bonesplitter is a Forsaken scholar and spellcaster stationed at Ghost Walker Post in Desolace. Appointed by Keldran to monitor demonic cult activity, he leverages his deep understanding of ancient lore to dismantle the Burning Blade. Maurin regards the cultists with sheer contempt, viewing them as fools blind to the dark entities pulling their strings.",h="Maurin Bonesplitter is a Forsaken scholar and spellcaster stationed at Ghost Walker Post in Desolace.",sec={{t="A Scholar Among Outcasts",b="While Ghost Walker Post primarily serves as a tauren and Horde outpost amidst the arid wastes of Desolace, Maurin Bonesplitter stands apart as one of its few undead occupants. Rather than a brutish soldier, Maurin is a learned spellcaster possessing extensive knowledge of forbidden histories and occult forces. His arcane aptitude and sharp intellect caught the eye of Keldran, who dispatched him to the region to observe the growing demonic presence and coordinate targeted strikes against it.",sp=0},{t="Contempt for the Burning Blade",b="Maurin directs most of his malice toward the Burning Blade cult entrenched across Desolace. He harbors utter disgust for their reckless ambition, mocking the cultists for failing to understand that their borrowed power merely binds them as thralls to their demonic masters. Through scrying spells and ritual knowledge, Maurin enlists Horde adventurers to systematically disrupt the cult's summonings and undermine their operations across the barren landscape.",sp=0}},faq={{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is a Forsaken warlock and scholar residing at Ghost Walker Post in Desolace. Appointed by Keldran, he uses his knowledge of ancient lore and dark magic to root out the Burning Blade cult operating in the region.",al={"maurin bonesplitter lore","who is maurin","maurin desolace"}},{q="Why is an undead staying at a tauren post?",a="Ghost Walker Post acts as a key Horde settlement in Desolace. Maurin was stationed there by Keldran specifically because the outpost provides an ideal staging ground to observe and combat the Burning Blade cultists infesting the surrounding wilderness.",al={"why is maurin at ghost walker post","undead in desolace"}},{q="What is Maurin's opinion of the Burning Blade?",a="Maurin views the Burning Blade with deep contempt. He sees them as pathetic, ignorant pawns who delusionally believe they wield true power, entirely oblivious to the reality that they are merely puppets of demonic masters.",al={"maurin burning blade","why does maurin hate burning blade"}},{q="Who sent Maurin Bonesplitter to Desolace?",a="Maurin was appointed to his role in Desolace by Keldran. Recognizing Maurin's extensive knowledge of cult practices and ancient lore, Keldran tasked him with actively hindering and eventually eliminating the Burning Blade from the zone.",al={"who sent maurin","maurin keldran","maurin boss"}},{q="What kind of tasks does Maurin give adventurers?",a="Maurin asks adventurers to investigate the Burning Blade and gather a Hatefury Shadowstalker scalp and a naga Oracle Crystal. He uses these reagents to break scrying wards and locate the demon lord behind the cult.",al={"maurin quests","what does maurin want"}},{q="Is Maurin affiliated with the Cenarion Circle or the Horde?",a="Maurin is a loyal member of the Forsaken and serves the Horde. He operates strictly from the Horde encampment at Ghost Walker Post, aiding Horde champions in cleansing the wastes of cultist activity.",al={"is maurin horde","maurin faction"}}},ang={["race:Undead"]="Maurin demonstrates that Forsaken strength relies as much on cunning arcane research and exploiting enemy weaknesses as it does on sheer necromantic might.",["class:Warlock"]="Warlocks will recognize Maurin's acute understanding of demonic pacts, though his disdain serves as a sharp reminder of the peril that comes with serving greater fiends.",["class:Mage"]="Mages visiting Ghost Walker Post can appreciate Maurin's calculated, intellectual approach to unraveling dark rituals with specialized counters.",["faction:Horde"]="Maurin represents Undercity's specialized support to the Horde's western outposts, bringing dark academic knowledge to assist tauren allies against demonic corruption."},kw={"burning blade","corrupter","desolace","forsaken","ghost walker post","keldran","maurin bonesplitter"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","topic:forsaken","quest:1431"},src={"Maurin Bonesplitter"}}
E["npc:misha"] = {t="npc",n="Misha",z="desolace",s="Misha is the loyal bear companion of Rexxar, the Champion of the Horde. She wanders Kalimdor faithfully at the half-ogre beastmaster's side.",h="Misha is the loyal bear companion of Rexxar, the Champion of the Horde.",sec={{t="A Boundless Bond",b="Misha is a brown bear who walks at the side of the wandering Rexxar, a solitary spirit who trusts beasts more than people. Together they have forged a fierce, protective partnership that has weathered countless wildernesses and bloody battles.",sp=0},{t="Defender of Durotar",b="Misha is far more than a tame pet; she is a seasoned warrior. She fought alongside Rexxar in the brutal conflict against Grand Admiral Daelin Proudmoore at Theramore Isle, helping ensure the young Horde's survival. When not in battle, her keen senses and strength serve as an extension of Rexxar's will.",sp=0},{t="Wilds of Kalimdor",b="Currently, travelers venturing along the long tracks through the Stonetalon Mountains, Desolace, and Feralas can spot Misha padding quietly beside Rexxar. Though fierce enough to tear apart any predator foolish enough to threaten them, she remains Rexxar's steadfast anchor in an otherwise untrustworthy world.",sp=0}},faq={{q="Who is Misha?",a="Misha is a ferocious brown bear and the lifelong companion of Rexxar, the Champion of the Horde. She wanders the wilds alongside him across central Kalimdor.",al={"rexxars bear","who is the bear with rexxar","misha bear"}},{q="Where can Misha be found right now?",a="Misha roams along the long patrol paths of the Stonetalon Mountains, Desolace, and Feralas, faithfully walking alongside Rexxar on his endless wanderings.",al={"misha location","where is misha","find misha"}},{q="Did Misha take part in the founding of Durotar?",a="Yes. Following the Third War, Misha accompanied Rexxar into battle against Grand Admiral Daelin Proudmoore's forces at Theramore Isle to defend the fledgling Horde.",al={"misha theramore","did misha fight daelin","misha third war"}},{q="Is Misha hostile to Alliance players?",a="Yes. As the companion of the Champion of the Horde, Misha will fiercely defend Rexxar and attack any Alliance trespassers who draw too close.",al={"can alliance attack misha","is misha aggressive"}},{q="Why does Rexxar prefer beasts like Misha to people?",a="Disillusioned by the deceit and warfare of humanoid races, Rexxar chose the solitude of the wilderness. He believes beasts are direct and honest, finding in Misha a companion devoid of betrayal.",al={"why does rexxar keep beasts","rexxar bear companion"}}},ang={["class:Hunter"]="For hunters, Misha represents the ultimate ideal of an animal companion: an unbreakable lifelong partnership forged through mutual respect rather than mere dominance.",["faction:Horde"]="Misha fought alongside Rexxar to secure the fledgling Horde's freedom at Theramore Isle, earning the quiet respect of veterans across Durotar."},kw={"bear","beastmaster","desolace","feralas","misha","rexxar","stonetalon"},rel={"zone:desolace","zone:feralas","zone:stonetalon","subzone:theramore-isle","zone:orgrimmar","topic:horde","topic:third-war"},src={"Misha"}}
E["npc:taiga-wisemane"] = {t="npc",n="Taiga Wisemane",z="desolace",s="Taiga Wisemane is a tauren elder residing in Shadowprey Village along the rugged western coast of Desolace. Watchful of demonic meddling across the barren wastes, he works to thwart the Burning Blade cult entrenched in the region. He directs Horde champions to disrupt demonic rituals and seal open gateways before the Burning Legion gains ground.",h="Taiga Wisemane is a tauren elder residing in Shadowprey Village along the rugged western coast of Desolace.",sec={{t="A Watchful Eye in Shadowprey",b="Though Shadowprey Village is predominantly a Darkspear troll fishing settlement tucked away against the ocean, Taiga Wisemane has taken up station there to monitor the dark sorceries stirring across Desolace. He remains acutely aware of the spiritual corruption bleeding into the soil, keeping his focus fixed eastward where shadow cults and demonic remnants fester among ancient ruins.",sp=0},{t="Stemming the Demonic Tide",b="The Burning Blade cult operates actively out of Thunder Axe Fortress, experimenting with dark artifacts to widen their influence. Recognizing the peril this poses to all inhabitants of Desolace, Taiga tasks capable adventurers with infiltrating the fortress to claim the Demon Box—an occult chest holding the Hand of Iruxos. Through this severing blow, he aims to rob the cult of the primary focus they rely upon to tear the veil between worlds.",sp=1},{t="Sealing the Coven's Portals",b="Securing the Hand of Iruxos is only the first step of Taiga's plan. At Mannoroc Coven to the south, the Burning Blade has already torn open active demonic rifts. By turning the dark focus against its creators, Taiga directs trusted champions to channel the artifact's energy directly into the gateways, closing the conduits before the Burning Legion can pour reinforcements into the heart of Kalimdor.",sp=1}},faq={{q="Who is Taiga Wisemane?",a="Taiga Wisemane is a tauren elder staying in Shadowprey Village on the western coast of Desolace. He acts as an advisor and quest giver dedicated to tracking and countering demonic rituals enacted by the Burning Blade cult throughout the region.",al={"who is taiga","taiga wisemane lore","taiga shadowprey"}},{q="Why is a tauren living in Shadowprey Village?",a="While Shadowprey is primarily a troll settlement, it is the Horde's main outpost along the Desolace coast. Taiga stays there to keep watch over the desolate wastes and enlist passing Horde travelers to neutralize nearby demonic threats.",al={"why is taiga in shadowprey","taiga troll village","tauren in troll town"}},{q="What is the Burning Blade doing in Desolace?",a="Operating from Thunder Axe Fortress and Mannoroc Coven, the Burning Blade cult is opening demonic gateways to summon forces of the Burning Legion into Kalimdor. Taiga works to undo their efforts before the wasteland is completely overrun.",al={"burning blade desolace","what are the cultists doing","thunder axe fortress cultists"}},{q="What is the Hand of Iruxos?",a="The Hand of Iruxos is a demonic artifact locked within a Demon Box at Thunder Axe Fortress. The Burning Blade means to use its foul energies to pry open portals to the Nether, but Taiga devises a way to turn the hand's magic against the rifts to seal them shut.",al={"hand of iruxos","what is demon box","demon box relic"}},{q="What happens at Mannoroc Coven?",a="Mannoroc Coven is an unholy site in southern Desolace where the Burning Blade successfully established demonic portals. Under Taiga Wisemane's instruction, adventurers take the Hand of Iruxos to the site to forcefully shut down the gateways.",al={"mannoroc coven portals","what is mannoroc coven","desolace portals"}},{q="Does Taiga belong to a specific tauren tribe?",a="Taiga carries the Wisemane surname, reflecting his role as an elder deeply concerned with spiritual balance and demonic corruption, though he serves the wider Horde gathered under the banner of the united tribes.",al={"taiga tribe","wisemane tribe","is taiga bloodhoof"}}},ang={["faction:Horde"]="Taiga provides crucial direction for Horde champions traveling through Desolace, ensuring that the outpost of Shadowprey Village remains shielded from demonic encroachment.",["race:Tauren"]="For tauren travelers, Taiga represents the duty to heal and protect Kalimdor from unnatural demonic blight, standing against the dark legacy that has scarred Desolace.",["class:Warlock"]="Warlocks will find Taiga's understanding of the Hand of Iruxos notable, as he uses the dark relic's own resonance to collapse demonic portals rather than banish them through holy rites."},kw={"burning blade","demon box","desolace","hand of iruxos","mannoroc coven","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"subzone:shadowprey-village","zone:desolace","subzone:thunder-axe-fortress","subzone:mannoroc-coven","topic:tauren","topic:horde"},src={"Taiga Wisemane"}}
E["npc:takata-steelblade"] = {t="npc",n="Takata Steelblade",z="desolace",s="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace. Dispatched from Orgrimmar by Keldran alongside Maurin Bonesplitter, he spearheads the Horde's local campaign against demonic corruption. His primary focus is eradicating the regional satyr population affiliated with the sinister Burning Blade.",h="Takata Steelblade is an orc warrior stationed at Ghost Walker Post in Desolace.",sec={{t="Sent to Desolace",b="Takata Steelblade was sent from the capital to Desolace under direct orders from Keldran, an influential figure in Orgrimmar committed to uncovering and purging demonic subversion. Operating out of the isolated Tauren encampment of Ghost Walker Post, Takata coordinates military efforts against the Legion-aligned forces plaguing the barren wastes.",sp=0},{t="Scourge of the Satyrs",b="While his companion Maurin Bonesplitter attempts to track and dismantle the clandestine Burning Blade cultists directly, Takata focuses on their demonic allies: the satyrs. Takata has orchestrated aggressive strikes against Desolace's corrupted satyrs, decimating their ranks to break the cult's local power structure and halt their spreading taint.",sp=0}},faq={{q="Who is Takata Steelblade?",a="Takata Steelblade is a veteran orc warrior stationed at Ghost Walker Post in Desolace. He directs operations against demonic forces and satyrs allied with the Burning Blade.",al={"takata","takata lore","who is takata"},it="identity"},{q="Who sent Takata to Desolace?",a="He was sent by Keldran from Orgrimmar to eliminate the threat posed by the Burning Blade and their demonic allies throughout the region.",al={"who sent takata","keldran connection","takata orders"},it="ties"},{q="What is the relationship between Takata and Maurin Bonesplitter?",a="Both were dispatched together by Keldran. While Maurin attempts to counter the Burning Blade cultists directly, Takata focuses his military strikes on the satyrs allied with them.",al={"takata and maurin","maurin bonesplitter"}},{q="Why is Takata hunting satyrs?",a="The satyrs in Desolace are actively allied with the Burning Blade cult, spreading demonic taint and threatening the Horde's foothold across the region.",al={"why kill satyrs","takata satyr","befouled by satyr"},it="wants"},{q="Where can Takata Steelblade be found?",a="He is located at Ghost Walker Post, a Horde camp in north-central Desolace.",al={"takata location","where is takata steelblade"},it="why_here",gp=true},{q="Whose side is Takata Steelblade on?",a="Takata Steelblade is loyal to the Horde and answers to Keldran in Orgrimmar. He works to secure the Horde's interests in Desolace by purging the demonic elements threatening Kalimdor, specifically targeting the wicked cults and demons aligned against his people.",al={"takata steelblade faction","takata loyalty","is takata horde"},it="side",add="a8c99361"},{q="Why is Takata Steelblade here?",a="Takata has taken up post at Ghost Walker Post on the orders of Keldran to lead the local offensive against demonic corruption. While his comrade Maurin Bonesplitter focuses strictly on the Burning Blade cult itself, Takata directs his wrath against the region's satyrs, waging a ruthless campaign to eliminate their presence entirely.",al={"why is takata in desolace","takata steelblade purpose","what is takata doing here"},it="why_here",add="683721f0"},{q="Why is Takata Steelblade famous or feared?",a="Takata is infamous among the foul inhabitants of Desolace for his devastating, systematic massacre of the local satyr population. He has earned a fearsome reputation by aggressively cutting down every satyr affiliated with the Burning Blade across the desolate wastes.",al={"takata reputation","why is takata feared","takata fame"},it="fame",add="a7138bd5"}},ang={["faction:Horde"]="Takata coordinates regional Horde defense in Desolace, working out of Ghost Walker Post to purge demonic infiltrators.",["race:Orc"]="Acting under orders from Orgrimmar's leadership, Takata embodies the orcish duty to stamp out any remnant of demonic servitude.",["class:Warrior"]="A master swordsman, Takata's campaign emphasizes decisive martial force to cut down demonic infiltrators."},kw={"bonesplitter","burning blade","desolace","ghost walker post","keldran","maurin","satyr","steelblade","takata"},rel={"subzone:ghost-walker-post","zone:desolace","npc:keldran","npc:maurin-bonesplitter","topic:satyr","quest:1431"},src={"Takata Steelblade"}}
E["quest:1052"] = {t="quest",n="Down the Scarlet Path",z="desolace",s="Brother Anton says your deeds against the undead in Desolace are only a start, because the plague's real danger is in Lordaeron. He gives you a letter of commendation bearing his seal for Raleigh the Devout in Southshore.",h="Brother Anton says your deeds against the undead in Desolace are only a start, because the plague's real...",sec={{t="Strongholds of the Crusade",b="Anton speaks proudly of the Scarlet Crusade's bastions of cleansing in Lordaeron. The Crusade claims strongholds all the way between Hearthglen and Tirisfal Glades. Anton says your work against the undead in Desolace has proven you, yet the plague's real danger is in Lordaeron.",sp=0},{t="A Letter for Southshore",b="Anton sends you to Southshore, a town in the Eastern Kingdoms, to look for a crusader called Raleigh the Devout. The letter carries Anton's seal, and Anton says it will win you an escort from Raleigh to a place of honor within the Scarlet Monastery.",sp=0},{t="Raleigh's Reaction",b="Raleigh breaks the seal and reads the letter. To hear that Anton still spreads word of the Scarlet Crusade troubles Raleigh, who tells you something here is beyond what you understand.",sp=1}},faq={{q="Who sends you on this journey?",a="Brother Anton gives you a sealed letter of commendation to carry to Raleigh the Devout.",al={"who gives down the scarlet path","quest giver down the scarlet path"}},{q="Where are you being sent?",a="You go to Southshore, in the Eastern Kingdoms, to find the crusader Raleigh the Devout.",al={"where to go","where is raleigh","down the scarlet path location"}},{q="What does Brother Anton say the letter will do?",a="Anton says that once Raleigh sees his sealed letter, Raleigh will take you to a place of honor within the Scarlet Monastery.",al={"what does the letter do","letter of commendation purpose"}},{q="What territory does the Scarlet Crusade claim in Lordaeron?",a="Brother Anton says the Scarlet Crusade holds strongholds stretching between Hearthglen and Tirisfal Glades, and he takes pride in those bastions of cleansing.",al={"scarlet crusade lands","where are scarlet crusade strongholds"}}},kw={"brother anton","down the scarlet path","hearthglen","letter of commendation","lordaeron","raleigh the devout","scarlet monastery","southshore","tirisfal glades"},rel={"quest:261","quest:6141","topic:scarlet-crusade","subzone:southshore","zone:scarlet","topic:lordaeron","subzone:hearthglen","zone:tirisfal"},m={start="Brother Anton",["end"]="Raleigh the Devout",level="40",faction="Alliance",id=1052},src={"Down the Scarlet Path (2)"}}
E["quest:1365"] = {t="quest",n="Khan Dez'hepah",z="desolace",s="After The Kolkar of Desolace, Felgur Twocuts sets you against the Kolkar's leader, Khan Dez'hepah. Many centaur clans fight one another across Desolace, and Felgur wants the Kolkar disrupted before the clans unite.",h="After The Kolkar of Desolace, Felgur Twocuts sets you against the Kolkar's leader, Khan Dez'hepah.",sec={{t="Divided Clans",b="The Kolkar are only one of the centaur clans of Desolace. Many roam the dry plains, fighting and dying at one another's hands. Felgur Twocuts does not mind, because the centaur are strong and brutal, and a united centaur people would be a fierce foe for the Horde. They must be dealt with before that happens.",sp=0},{t="The Kolkar Leader",b="Felgur's first move is to disrupt the Kolkar by killing their leader, Khan Dez'hepah. The Kolkar Village lies northeast of where Felgur stands, and Felgur wants the khan's head brought back.",sp=0}},faq={{q="Why does Felgur Twocuts want Khan Dez'hepah dead?",a="Felgur worries that the centaur clans may unite against the Horde. Killing Khan Dez'hepah is meant to disrupt the Kolkar clan first.",al={"why kill dezhepah","khan dezhepah purpose","reason for killing dezhepah"}},{q="Where is Khan Dez'hepah located?",a="In the Kolkar Village, northeast of Felgur Twocuts in Desolace.",al={"khan dezhepah location","where is dezhepah","kolkar village location"}},{q="What does Felgur want brought back?",a="Khan Dez'hepah's head, brought back to Felgur Twocuts.",al={"khan dezhepah proof","what to bring felgur"}},{q="What comes before Khan Dez'hepah?",a="The Kolkar of Desolace. After it, Felgur Twocuts sends you against the Kolkar leader, Khan Dez'hepah.",al={"previous quest dezhepah","prerequisite for khan dezhepah"}}},kw={"centaur","desolace","dez'hepah","felgur twocuts","khan dez'hepah","kolkar","kolkar village"},rel={"npc:felgur-twocuts","topic:kolkar-clan","topic:centaur","quest:1362","zone:desolace"},m={start="Felgur Twocuts",["end"]="Felgur Twocuts",level="35",faction="Horde",id=1365},src={"Khan Dez'hepah (quest)"}}
E["quest:1366"] = {t="quest",n="Centaur Bounty",z="desolace",s="After Khan Dez'hepah, Felgur Twocuts says the scared centaur clans must now be bled. Hunt centaur of any clan across Desolace and bring Felgur fifteen of their ears.",h="After Khan Dez'hepah, Felgur Twocuts says the scared centaur clans must now be bled.",sec={{t="Time to Bleed Them",b="Felgur Twocuts says that now the centaur clans have been scared, it is time to bleed them. Whenever you travel Desolace, hunt centaur. Felgur does not care which clan you hunt, only that you gather ears, fifteen of them. Thinning their numbers will weaken their resolve and put an end to any thoughts of expansion.",sp=0},{t="Felgur's Verdict",b="When you return, Felgur says the centaur must by now know your name, and respect and fear it. They know the banner you ride under as well: the Horde's.",sp=1}},faq={{q="Who orders this bounty on the centaur?",a="Felgur Twocuts, in Desolace. Fifteen centaur ears are to be brought back to Felgur.",al={"who gives centaur bounty","centaur bounty questgiver"}},{q="Which centaur clans need to be hunted?",a="Any of them. Felgur does not care which clan you hunt, only that you gather ears.",al={"which centaur do i kill","what clan for centaur bounty"}},{q="Why does Felgur want so many centaur ears?",a="To weaken the centaur numbers. Fewer centaur means weaker resolve, and it stamps out any thoughts of expansion.",al={"why kill centaur desolace","reason for centaur bounty"}},{q="What came before this bounty?",a="It follows Khan Dez'hepah. Felgur says the centaur clans have been scared, and now it is time to bleed them.",al={"centaur bounty prereq","previous quest centaur bounty"}}},kw={"centaur","centaur bounty","centaur ears","desolace","felgur twocuts","khan dez'hepah"},rel={"npc:felgur-twocuts","zone:desolace","topic:centaur","topic:horde"},m={start="Felgur Twocuts",["end"]="Felgur Twocuts",level="31",faction="Horde",id=1366},src={"Centaur Bounty (Horde)"}}
E["quest:1367"] = {t="quest",n="Magram Alliance",z="desolace",s="Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn how all of them can be beaten. Siding with the Magram means slaying their enemies the Gelkis, then speaking with the Magram spokesman Warug at the edge of Magram Village, in the southeast of Desolace.",h="Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn...",sec={{t="Hatred as a Weapon",b="Gurda Wildmane's plan is to exploit the centaurs' hatred of each other. A single clan is chosen as ally, and what it teaches shows how to defeat every clan. Choose the Magram and you cut down the Gelkis, their foes, which wins you respect among the Magram.",sp=0},{t="The Spokesman",b="Once you have earned enough respect, Warug, the Magram spokesman, is waiting on the outskirts of Magram Village in southeast Desolace. Before that he has nothing to say to you. The Magram have no words for the weak and kill them instead, so he sends you off to prove your strength against many Gelkis.",sp=0},{t="Warug's Judgment",b="Warug tells you the Gelkis weep at the sound of your name, afraid of you and hating you as they hate the Magram. Maybe, he allows, you are as strong as the Magram. He will see.",sp=1}},faq={{q="Who proposes an alliance with the Magram?",a="Gurda Wildmane, who wants to pit the centaur clans' hatred against them by allying with one clan and learning from it how to beat all of them.",al={"who gives magram alliance","magram quest giver","gurda wildmane quest"}},{q="How do you earn the respect of the Magram?",a="By slaying their foes, the Gelkis.",al={"how to get friendly with magram","magram reputation","make magram friendly"}},{q="Where is Warug?",a="On the outskirts of Magram Village, in southeast Desolace. He is the Magram spokesman.",al={"where is warug","find warug","warug location"}},{q="Why does Warug refuse to speak at first?",a="He says the Magram have no talk for the weak and kill them. First, prove your strength by slaying many Gelkis.",al={"why won't warug talk","warug angry","warug dialogue"}}},kw={"centaur","desolace","gelkis","gurda wildmane","magram","magram village","warug"},rel={"zone:desolace","subzone:magram-village","topic:centaur"},m={start="Gurda Wildmane",["end"]="Warug",level="33",faction="Horde",id=1367},src={"Magram Alliance"}}
E["quest:1368"] = {t="quest",n="Gelkis Alliance",z="desolace",s="Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn how all of them can be beaten. Siding with the Gelkis means killing their worst enemy, the Magram, then meeting Uthek the Wise, a shaman of the Gelkis, on the edge of Gelkis Village in the southwest of Desolace.",h="Gurda Wildmane proposes turning the centaur clans' hatred against them: befriend one clan and use it to learn...",sec={{t="Hatred as a Weapon",b="Gurda Wildmane's plan is to exploit the centaurs' hatred of each other. A single clan is chosen as ally, and what it teaches shows how to defeat every clan. Choose the Gelkis and you kill the Magram, whom the Gelkis hate most, to win their respect.",sp=0},{t="The Shaman",b="Once you have won their respect, Uthek the Wise, shaman of the Gelkis, is to be met on the outskirts of Gelkis Village in southwest Desolace. Before then you are not welcome there: Uthek says you tread on Gelkis earth, and friendship must be proven by killing Magram centaur. Come back once Magram blood has soaked the ground.",sp=0},{t="Uthek's Word",b="Uthek says the earth tells of how many Magram you have killed, and that this is good. To a friend of the Gelkis, Uthek has more work to give.",sp=1}},faq={{q="Who proposes an alliance with the Gelkis?",a="Gurda Wildmane, who wants to pit the centaur clans' hatred against them by allying with one clan and learning from it how to beat all of them.",al={"who gives gelkis alliance","gelkis alliance quest giver"}},{q="How do you earn the favor of the Gelkis?",a="By killing the Magram, whom the Gelkis hate most.",al={"how to get friendly with gelkis","gelkis rep"}},{q="Who do you speak to among the Gelkis?",a="Uthek the Wise, a Gelkis shaman, on the outskirts of Gelkis Village in southwest Desolace.",al={"where is uthek","uthek the wise location"}},{q="What does Uthek require before welcoming you?",a="Uthek says you are not welcome on Gelkis earth until you prove friendship by killing Magram centaur.",al={"why does uthek reject me","gelkis village hostile"}}},kw={"centaur","desolace","gelkis","gelkis village","gurda wildmane","magram","uthek the wise"},rel={"subzone:gelkis-village","topic:centaur","zone:desolace","quest:1370"},m={start="Gurda Wildmane",["end"]="Uthek the Wise",level="33",faction="Horde",id=1368},src={"Gelkis Alliance"}}
E["quest:1369"] = {t="quest",n="Broken Tears",z="desolace",s="Warug says the Gelkis foolishly believe the centaur mother, Theradras, protects them. He sends you into the cave in their village to destroy the crystals they hoard there, the tears of Theradras, and bring him three of the broken pieces.",h="Warug says the Gelkis foolishly believe the centaur mother, Theradras, protects them.",sec={{t="Crystals in the Cave",b="Warug scorns the Gelkis for trusting Theradras, mother of the centaur, to protect them. To him no one protects the centaur, and the Magram, being the strongest, need no protection. He sends you to the cave in the Gelkis village, where they keep a hoard of crystals called the tears of Theradras. Smash them and bring Warug three broken pieces. He will only trust you with this if you are no enemy of the Magram.",sp=0},{t="Warug's Boast",b="Warug is delighted: with the tears broken, the Gelkis will see that Theradras cannot help them, and no tears of hers will fall when the Magram crush them. He declares the Magram will rule, and calls you wise to side with the strongest.",sp=1}},faq={{q="Who is Warug?",a="A Magram centaur in Magram Village in Desolace. He asks you to destroy the tears of Theradras in the Gelkis cave.",al={"warug","who gives broken tears","broken tears quest giver"}},{q="What are the tears of Theradras?",a="Crystals the Gelkis hoard in a cave in their village.",al={"tears of theradras","broken tears lore","gelkis crystals"}},{q="Why does Warug want the tears destroyed?",a="The Gelkis think the centaur mother, Theradras, protects them. Warug calls them stupid, says the Magram need no protection, and wants to show the Gelkis they are wrong.",al={"why destroy the tears","magram motive","why break crystals"}},{q="Where are the crystals found?",a="In the cave in the Gelkis village. Warug wants three broken pieces brought back to him.",al={"where are broken tears","gelkis cave location","where are the tears"}}},kw={"broken tears","centaur","desolace","gelkis","magram","theradras","warug"},rel={"subzone:magram-village","topic:centaur","quest:1371","zone:desolace"},m={start="Warug",["end"]="Warug",level="33",id=1369},src={"Broken Tears (quest)"}}
E["quest:1370"] = {t="quest",n="Stealing Supplies",z="desolace",s="Uthek the Wise says meat gives the Gelkis their strength, and that the Magram keep extra stores so they can fight longer between hunts. You are sent to raid the Magram village to the east and bring back six bags of dried meat.",h="Uthek the Wise says meat gives the Gelkis their strength, and that the Magram keep extra stores so they can...",sec={{t="Meat and Strength",b="Between wars the Gelkis hunt, because meat means strength and a full belly fights harder than an empty one. Uthek the Wise says the Magram keep spare stock to last them between hunts. Raid their village to the east, take those stores, and their strength will fail. Six bags of crudely dried meat are wanted, to be brought to Uthek at the Gelkis Village.",sp=0}},faq={{q="Who sends you to take these supplies?",a="Uthek the Wise of the Gelkis, in Desolace.",al={"quest giver","who gives stealing supplies","uthek the wise"}},{q="Why does Uthek want the Magram meat taken?",a="To the Gelkis, meat is strength. The Magram keep a reserve so they can keep fighting between hunts, and Uthek says taking it would sap them.",al={"why steal meat","magram food","reason for meat raid"}},{q="Where are the Magram supplies kept?",a="In the Magram village, to the east.",al={"where is magram village","where are supplies","magram location"}},{q="How much meat does Uthek want?",a="Six bags of crudely dried meat, which Uthek the Wise collects at the Gelkis Village.",al={"how much meat","what do i bring uthek"}}},kw={"centaur","desolace","gelkis","magram","meat","supplies","uthek"},rel={"subzone:gelkis-village","zone:desolace","topic:centaur","quest:1382"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="35",id=1370},src={"Stealing Supplies"}}
E["quest:1371"] = {t="quest",n="Gizmo for Warug",z="desolace",s="Warug, in the Magram Village, remembers a gnome who once came to Desolace with a cart of strange things. He kept a wooden human from that cart until he broke it, and now he wants a new one: an advanced target dummy.",h="Warug, in the Magram Village, remembers a gnome who once came to Desolace with a cart of strange things.",sec={{t="The Gnome's Cart",b="A little gnome once came to Desolace, long ago, with horses and a cart. The cart held curious things: some burned in different colors, others moved though they were not alive. Warug killed the gnome, but first the gnome made him laugh. Warug kept his favorite thing from the cart, a human made of wood that waved at him until he hit it and broke it. Now he wants a new one, an advanced target dummy, and expects it from anyone who is no enemy of the Magram.",sp=0}},faq={{q="Who is Warug?",a="Warug is a Magram centaur, found in Magram Village. He expects those he deals with to stay in the Magram's good standing.",al={"warug","who gives gizmo for warug"}},{q="What does Warug want?",a="An advanced target dummy, to replace the wooden human from the gnome's cart that he broke.",al={"what item does warug need","warug gizmo item"}},{q="Why does Warug want a target dummy?",a="Long ago he killed a gnome who came to Desolace with a cart of strange, funny things. The gnome made him laugh, and Warug's favorite was a wooden figure of a human that waved at him until he hit it and broke it. He wants a new one.",al={"why does warug want a dummy","warug dummy reason"}},{q="What comes before this in the Magram story?",a="It follows Broken Tears, earlier in your dealings with the Magram.",al={"gizmo for warug chain","what comes before gizmo for warug"}}},kw={"centaur","desolace","gnome","magram","target dummy","warug"},rel={"subzone:magram-village","zone:desolace","topic:centaur","topic:gnome","topic:human"},m={start="Warug",["end"]="Warug",level="35",id=1371},src={"Gizmo for Warug"}}
E["quest:1373"] = {t="quest",n="Ongeku",z="desolace",s="Uthek the Wise of the Gelkis says you still have more to prove, and that for now the Gelkis will take on the Magram without your help. The earth has whispered to Uthek of draenethyst, and you are sent far away to the Swamp of Sorrows for a shard held by the lost one Ongeku.",h="Uthek the Wise of the Gelkis says you still have more to prove, and that for now the Gelkis will take on the...",sec={{t="A Crystal from Far Away",b="After Stealing Supplies, Uthek the Wise tells you that your next undertaking lies a long way off. Those who listen hear many secrets in the earth, and one Uthek has heard is of a red crystal called draenethyst, newly arrived in this land and brought from a place of flying mountains and ruling demons. A shard of it, Uthek says, will make the magic strong. The lost one Ongeku holds a shard in the Swamp of Sorrows in the Eastern Kingdoms. When you return, Uthek will look for proof that the Gelkis can still call you friend.",sp=0}},faq={{q="Who is Uthek the Wise?",a="A Gelkis centaur at Gelkis Village in Desolace who says the earth whispers its secrets to those who listen.",al={"uthek","gelkis elder","centaur quest giver"}},{q="What is draenethyst?",a="A red crystal that Uthek calls new to our earth. He says it comes from a land of flying mountains where demons rule.",al={"draenethyst shard","red crystal","what is draenethyst"}},{q="Who is Ongeku?",a="A Lost One who holds a shard of draenethyst in the central Swamp of Sorrows, in the Eastern Kingdoms.",al={"where is ongeku","ongeku location","find ongeku"}},{q="Why does Uthek want a draenethyst shard?",a="Uthek says a shard will make the magic strong.",al={"why get draenethyst","uthek magic"}},{q="What came before this?",a="Stealing Supplies, which Uthek gave you earlier.",al={"previous quest","prerequisite"}}},kw={"desolace","draenethyst","gelkis","lost one","magram","ongeku","swamp of sorrows","uthek the wise"},rel={"subzone:gelkis-village","quest:1370","zone:desolace","zone:swampofsorrows","topic:centaur","subzone:stonard","subzone:nethergarde-keep","subzone:darkshire"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="37",id=1373},src={"Ongeku (quest)"}}
E["quest:1374"] = {t="quest",n="Khan Jehn",z="desolace",s="Following Ongeku, Uthek the Wise tells you the earth says the Magram are growing weak, and that the hour has come to slay their Khan. Uthek wants the head of Khan Jehn brought to Gelkis Village.",h="Following Ongeku, Uthek the Wise tells you the earth says the Magram are growing weak, and that the hour has...",sec={{t="The Magram Khan",b="Uthek the Wise at Gelkis Village says the earth speaks to Uthek, and it tells of the Magram growing weak. Uthek names their Khan, Jehn, as the one to strike down and asks for the head of the Magram Khan. Uthek expects you to still count as a friend of the Gelkis when you come back.",sp=0}},faq={{q="Who is Khan Jehn?",a="The Khan of the Magram centaur.",al={"khan jehn","who is jehn","magram leader"}},{q="Why does Uthek the Wise want Khan Jehn dead?",a="Uthek says the earth tells him the Magram grow weak, so now is the time to kill their Khan.",al={"why kill jehn","uthek motivation","why kill magram khan"}},{q="What came before this?",a="It comes after Ongeku.",al={"what comes before khan jehn","chain order","previous quest"}},{q="Where is Uthek the Wise?",a="At Gelkis Village in Desolace.",al={"uthek location","where is uthek"}}},kw={"centaur","desolace","gelkis","gelkis village","head of jehn","khan jehn","magram","uthek the wise"},rel={"subzone:gelkis-village","zone:desolace","topic:centaur","quest:1373","quest:1380"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="37",id=1374},src={"Khan Jehn (quest)"}}
E["quest:1375"] = {t="quest",n="Khan Shaka",z="desolace",s="Warug of the Magram, pleased with your help after Gizmo for Warug, now wants the head of Khan Shaka, the Khan of the Gelkis. He means to stare at it and laugh at his enemy.",h="Warug of the Magram, pleased with your help after Gizmo for Warug, now wants the head of Khan Shaka, the Khan...",sec={{t="A Rival Khan",b="In Magram Village, Warug tells you that you have helped the Magram and he likes you. Now he wants you to kill Khan Shaka, the Khan of the Gelkis, and bring him the head. He says he wants to stare at it and laugh at him. He expects you to stay on good terms with the Magram.",sp=0}},faq={{q="Who is Khan Shaka?",a="The Khan of the Gelkis centaur clan in Desolace, whose head Warug of the Magram wants.",al={"khan shaka lore","who is shaka","shaka centaur"}},{q="Why does Warug want Khan Shaka dead?",a="He wants Shaka's head so he can stare at it and laugh at him.",al={"why kill shaka","warug shaka grudge"}},{q="Where is Warug?",a="In Magram Village in Desolace.",al={"khan shaka location","where is warug"}},{q="What led up to this?",a="Gizmo for Warug, after which Warug says he likes you for helping the Magram.",al={"khan shaka prerequisites","previous quest shaka"}}},kw={"centaur","desolace","gelkis","head of khan shaka","khan shaka","magram","warug"},rel={"zone:desolace","subzone:magram-village","topic:centaur","quest:1371"},m={start="Warug",["end"]="Warug",level="37",id=1375},src={"Khan Shaka (quest)"}}
E["quest:1380"] = {t="quest",n="Khan Hratha",z="desolace",s="Uthek the Wise recalls how you helped the Gelkis against the Magram, and now asks you to strike at the Maraudine by slaying their clan's leader, Khan Hratha. Hratha holds a piece of a key, and Uthek wants it brought to him.",h="Uthek the Wise recalls how you helped the Gelkis against the Magram, and now asks you to strike at the...",sec={{t="Challenging the Maraudine",b="Uthek the Wise says the Gelkis now need help against the Maraudine. The Maraudine War Horn stands on a tall bluff in the Valley of Spears, and sounding it is how Khan Hratha is called out. Yet the horn is useless without a warhorn mouthpiece, which is rare and carried only by trusted Maraudine centaur. When the horn sounds, more centaur arrive, and Hratha comes last.",sp=0},{t="A Piece of a Key",b="Khan Hratha holds a piece of a key, and Uthek wants it brought to Gelkis Village.",sp=0},{t="On Your Return",b="On your return, Uthek exults that Hratha is dead and the Maraudine are doomed. He vows that the Gelkis will remember you once they rule this land, and that the earth's spirits will sing your name forever.",sp=1}},faq={{q="Who sends you to fight Khan Hratha?",a="Uthek the Wise, at Gelkis Village in Desolace, asks it of those who have helped the Gelkis.",al={"who gives khan hratha","khan hratha quest giver","where to get khan hratha"}},{q="How is Khan Hratha brought out to fight?",a="Uthek points you to the Maraudine War Horn in the Valley of Spears, which has to be sounded. Centaur answer it, and Hratha follows.",al={"khan hratha location","where is khan hratha","find khan hratha"}},{q="How do you blow the Maraudine War Horn?",a="The horn is useless without a warhorn mouthpiece, and only trusted Maraudine centaur carry those, rarely.",al={"warhorn mouthpiece","how to use maraudine war horn","blow maraudine war horn"}},{q="What comes before this?",a="It follows Khan Jehn. Uthek reminds you that you helped the Gelkis against the Magram.",al={"khan hratha prerequisites","what quest before khan hratha","khan hratha chain"}},{q="What does Khan Hratha hold?",a="Khan Hratha holds a piece of a key, which Uthek asks you to bring to him in Gelkis Village.",al={"khan hratha item","maraudine key fragment","what does hratha drop"}}},kw={"centaur","desolace","gelkis village","khan hratha","maraudine","maraudine war horn","uthek the wise","valley of spears"},rel={"subzone:gelkis-village","subzone:valley-of-spears","topic:centaur","zone:desolace"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="42",id=1380},src={"Khan Hratha (Gelkis)"}}
E["quest:1381"] = {t="quest",n="Khan Hratha",z="desolace",s="Warug announces the death of the Gelkis Khan and says the Maraudine are next. Warug sends you after their Khan, Hratha, and wants the piece of a key that Hratha carries.",h="Warug announces the death of the Gelkis Khan and says the Maraudine are next.",sec={{t="A Horn on the Bluff",b="Warug wants the Maraudine Khan, Hratha, dead. A horn on a bluff in the Valley of Spears calls him out, but it will not sound without a mouthpiece, and a mouthpiece is found by killing Maraudine centaur. After the blast, Maraudine centaur gather at the tower, and Hratha shows himself in the end.",sp=0},{t="A Piece of a Key",b="Hratha holds part of a key, and Warug wants it brought to Warug in Magram Village. Warug expects you to prove yourself an ally of the Magram.",sp=0},{t="Masters of the Centaur",b="With Hratha dead, Warug proclaims the Magram the mightiest of the centaur, destined to crush their rivals and rule Desolace. Warug says you will be remembered and spared when the rest are trampled.",sp=1}},faq={{q="Who sends you to defeat Khan Hratha?",a="Warug, at Magram Village in Desolace, after the Gelkis Khan's death.",al={"who gives khan hratha","khan hratha quest giver"}},{q="How do you reach Khan Hratha?",a="Warug says the way to face Hratha is to sound the horn on the bluff in the Valley of Spears. It needs a mouthpiece, found by killing Maraudine centaur, and the centaur then gather at the tower before Hratha appears.",al={"how to summon hratha","find khan hratha","blow horn valley of spears"}},{q="Where does Khan Hratha appear?",a="Hratha appears at the tower in the Valley of Spears once the horn has been blown and the Maraudine centaur who gather there are cut down.",al={"khan hratha location","where is hratha"}},{q="What does Khan Hratha hold?",a="Hratha holds part of a key, and Warug asks you to bring that piece to Warug.",al={"what does hratha drop","maraudine key fragment"}}},kw={"desolace","key fragment","khan hratha","magram","maraudine","valley of spears","war horn","warug"},rel={"subzone:magram-village","subzone:valley-of-spears","zone:desolace","topic:centaur","quest:1375"},m={start="Warug",["end"]="Warug",level="42",id=1381},src={"Khan Hratha (Magram)"}}
E["quest:1382"] = {t="quest",n="Strange Alliance",z="desolace",s="Captain Pentigast sees luck in the way the centaur clans of Desolace fight each other, since as one force they could not be stopped. The Gelkis are locked in brutal war with the Magram, so Pentigast sends you to Uthek the Wise in southwestern Desolace to seek an alliance.",h="Captain Pentigast sees luck in the way the centaur clans of Desolace fight each other, since as one force...",sec={{t="Divided Clans",b="Captain Pentigast counts it good fortune that the centaur clans war on one another, for joined together they could not be stopped. Pentigast wants to push that edge. The Gelkis and Magram are locked in brutal war, so striking at the Magram might win the Gelkis over.",sp=0},{t="Seeking Uthek",b="Uthek the Wise can be found where the Gelkis camps begin, in the southwest of Desolace, and through her an alliance might be struck. She turns you away at first, telling you to leave and to return after killing many Magram.",sp=0},{t="Uthek's Answer",b="Once enough Magram have fallen to you, Uthek says the Gelkis now whisper your name, and she approves. She is willing to talk about what you can offer the clan and what it can offer you.",sp=1}},faq={{q="Who sends you to contact the Gelkis?",a="Captain Pentigast, who hopes an alliance can be struck with the Gelkis clan.",al={"who gives strange alliance","strange alliance quest giver","who starts strange alliance"}},{q="Where is Uthek the Wise located?",a="Where the Gelkis camps begin, in the southwest of Desolace.",al={"uthek location","find uthek the wise","where is uthek"}},{q="Why will Uthek the Wise not talk to newcomers right away?",a="She tells you to leave and to return after killing many Magram.",al={"why uthek hostile","uthek won't speak","how to talk to uthek"}},{q="Why does the Alliance want a pact with the Gelkis?",a="Captain Pentigast reasons that centaur clans joined as one could not be stopped, so their quarrels are a stroke of luck. The Gelkis are at war with the Magram, so attacking the Magram may win Gelkis friendship.",al={"why ally with gelkis","alliance centaur reason","why gelkis clan"}}},kw={"centaur","desolace","gelkis","magram","pentigast","strange alliance","uthek"},rel={"quest:1384","zone:desolace","topic:centaur","topic:alliance"},m={start="Captain Pentigast",["end"]="Uthek the Wise",level="35",faction="Alliance",id=1382},src={"Strange Alliance"}}
E["quest:1384"] = {t="quest",n="Raid on the Kolkar",z="desolace",s="After Strange Alliance, Uthek the Wise sends you against the Kolkar centaurs to the northeast. Kill them, take their charms, and bring ten of those charms back to Uthek.",h="After Strange Alliance, Uthek the Wise sends you against the Kolkar centaurs to the northeast.",sec={{t="Contempt for Kolkar Magic",b="Uthek scoffs at the Kolkar centaurs for thinking their magic strong; in Uthek's view they know nothing of magic. You go northeast to the Kolkar, kill them, and take their charms. Uthek wants ten Crude Charms to throw in the fire, laughing as they burn.",sp=0},{t="Uthek's Verdict",b="Uthek praises the deed as a good one for the Gelkis. The Kolkar are feeble and doomed, Uthek says, and their magic will not save them. Having seen your work, they will fear all the more, and fear makes them feebler. In Gelkis lands, the feeble soon die.",sp=1}},faq={{q="Who is Uthek the Wise?",a="Uthek the Wise waits in Gelkis Village in Desolace. Uthek wants the Kolkar's charms.",al={"who gives raid on the kolkar","uthek","uthek the wise lore"}},{q="Where are the Kolkar located?",a="To the northeast, according to Uthek.",al={"where to find kolkar","kolkar location desolace"}},{q="What are the Crude Charms?",a="Charms taken from the Kolkar. Uthek wants ten of them to throw in the fire and laugh.",al={"crude charm","kolkar charms"}},{q="How does this fit into the Gelkis chain?",a="It follows Strange Alliance.",al={"gelkis chain","what comes before raid on the kolkar"}}},kw={"centaur","crude charms","desolace","gelkis","kolkar","uthek"},rel={"quest:1382","quest:1370","subzone:gelkis-village","topic:centaur","zone:desolace"},m={start="Uthek the Wise",["end"]="Uthek the Wise",level="32",id=1384},src={"Raid on the Kolkar"}}
E["quest:1385"] = {t="quest",n="Brutal Politics",z="desolace",s="Captain Pentigast believes whichever centaur clan wins the wars of Desolace will spill out and threaten the Alliance strongholds. To learn how to beat them, Pentigast wants an alliance with one clan: fight the Gelkis, win over the Magram, and speak with Warug.",h="Captain Pentigast believes whichever centaur clan wins the wars of Desolace will spill out and threaten the...",sec={{t="A Land at War",b="War rages across Desolace, centaur against centaur, and the Alliance believes the winner will spill out against its strongholds. That cannot be allowed. To learn how to beat the centaurs, Captain Pentigast says, the Alliance needs one of the clans as a friend.",sp=0},{t="The Magram",b="The Magram fight the Gelkis, so striking at the Gelkis might make the Magram weigh an alliance. Earn their favor, then go to Warug in the Magram village, in Desolace's southeast. Warug warns that to be a friend of the Magram, you must kill Gelkis.",sp=0}},faq={{q="Why does the Alliance want an alliance with a centaur clan?",a="Captain Pentigast believes the victor of the centaur wars will spill out and threaten Alliance strongholds. To learn how to beat them, the Alliance needs one of the clans as a friend.",al={"why ally with magram","pentigast plan","centaur alliance reason"}},{q="How do you earn the favor of the Magram?",a="The Magram are at war with the Gelkis, and fighting the Gelkis may lead them to consider an alliance. Warug says that to be the Magram's friend, you must kill Gelkis.",al={"how to get magram rep","magram friendly","killing gelkis"}},{q="Where is Warug?",a="In the Magram village, in Desolace's southeast.",al={"warug location","where is warug","magram contact"}}},kw={"brutal politics","centaur","desolace","gelkis","magram","pentigast","warug"},rel={"quest:1386","subzone:magram-village","topic:centaur","zone:desolace","topic:alliance"},m={start="Captain Pentigast",["end"]="Warug",level="35",faction="Alliance",id=1385},src={"Brutal Politics"}}
E["quest:1386"] = {t="quest",n="Assault on the Kolkar",z="desolace",s="After Brutal Politics, Warug in Magram Village wants proof that you can kill Kolkar the way the Magram do. Head north and slay Kolkar centaurs, scouts and maulers.",h="After Brutal Politics, Warug in Magram Village wants proof that you can kill Kolkar the way the Magram do.",sec={{t="We Laugh and We Kill",b="Warug sneers that the Kolkar believe themselves strong while the Magram laugh at them as they kill them. Warug wants you to prove you can kill Kolkar as the Magram do, so you head north: twelve Kolkar centaurs, twelve scouts and six maulers are to fall.",sp=0},{t="Warug's Approval",b="When you return, Warug says the Kolkar fear you now. Warug hopes you laughed as you killed them, because laughing while you kill lets the enemy see its own weakness.",sp=1}},faq={{q="Who sends you to attack the Kolkar?",a="Warug, of the Magram, in Magram Village in Desolace.",al={"who gives assault on the kolkar","quest giver assault on the kolkar","where to get assault on the kolkar"}},{q="What came before this step?",a="It follows Brutal Politics.",al={"previous quest","prereq assault on the kolkar","assault on the kolkar prerequisite"}},{q="Where are the Kolkar located?",a="Warug tells you to head north to find them.",al={"kolkar location","where are kolkar centaur","where to find kolkar"}},{q="Why does Warug want the Kolkar killed?",a="Warug mocks the Kolkar for thinking themselves strong, and wants you to show you can kill them as the Magram do.",al={"why kill kolkar","magram kolkar rivalry","why does warug hate kolkar"}}},kw={"brutal politics","centaur","desolace","kolkar","magram","magram village","warug"},rel={"quest:1385","subzone:magram-village","topic:centaur","zone:desolace"},m={start="Warug",["end"]="Warug",level="32",id=1386},src={"Assault on the Kolkar"}}
E["quest:1387"] = {t="quest",n="Centaur Bounty",z="desolace",s="Corporal Melkins at Nijel's Point says every centaur clan in Desolace shares one trait, cruelty, and that peace will not come while the centaur remain. Melkins asks you to hunt them across the land and bring fifteen of their ears.",h="Corporal Melkins at Nijel's Point says every centaur clan in Desolace shares one trait, cruelty, and that...",sec={{t="One Thing in Common",b="At Nijel's Point, Corporal Melkins describes a centaur race split among many clans, each with a leader and plans of its own, yet alike in cruelty. Peace, Melkins says, will only come if the centaurs are removed.",sp=0},{t="Ears for the Alliance",b="Wandering Desolace, you hunt centaur and take their ears. Melkins wants a great many, fifteen in all, and calls the work a service to the Alliance that brings the war's end nearer.",sp=0}},faq={{q="Who issues the bounty on the centaur?",a="Corporal Melkins, stationed at Nijel's Point in Desolace.",al={"centaur bounty questgiver","who gives centaur bounty","melkins bounty"}},{q="Why does Corporal Melkins want the centaur killed?",a="Melkins says the clans differ in leaders and aims but are all cruel, and that peace is impossible while the centaur remain.",al={"why kill centaur","melkins motive","why centaur ears"}},{q="What does Corporal Melkins ask you to bring?",a="Fifteen centaur ears, taken from centaur you hunt while wandering Desolace.",al={"what to collect","centaur bounty items","centaur bounty trophy"}},{q="Which centaur clans need to be hunted?",a="Melkins names no single clan, saying all the clans share cruelty, and asks only that you hunt centaur in Desolace.",al={"which centaurs","centaur clan target","what clan for ears"}}},kw={"alliance","bounty","centaur","centaur ear","corporal melkins","desolace","ears","nijel's point"},rel={"subzone:nijel-s-point","topic:centaur","zone:desolace","topic:alliance"},m={start="Corporal Melkins",["end"]="Corporal Melkins",level="31",faction="Alliance",id=1387},src={"Centaur Bounty (Alliance)"}}
E["quest:1437"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="Vahlarriel Demonslayer has come to Desolace to learn what became of two missing nobles of House Malem, a Darnassian merchant family. Their father fears the worst, and the last word of the pair places them in the Stonetalon Mountains some weeks back. Vahlarriel asks you to find their wagon.",h="Vahlarriel Demonslayer has come to Desolace to learn what became of two missing nobles of House Malem, a...",sec={{t="Two Missing Nobles",b="Vahlarriel Demonslayer is looking for Tyranis and Dalinda Malem, whose father fears the worst and has charged Vahlarriel with doing everything possible to find them. The search has barely begun, and Vahlarriel hopes it will not keep them in Desolace long. The pair were last reported crossing the Stonetalon Mountains some weeks ago. Vahlarriel asks you to find their wagon in Desolace and to come at once when you do. Its charred remains lie there, with a chest among them.",sp=0},{t="Among the Wreckage",b="Rummaging through the wreck, you can tell the wagon fell to spells and weapons alike. The fight looks to have been brief and lopsided, with no blood and no bodies left behind. Whoever did this was efficient and swift.",sp=1}},faq={{q="Who is Vahlarriel looking for?",a="Tyranis and Dalinda Malem, two nobles of House Malem, a Darnassian merchant family.",al={"who is missing","who are the nobles","house malem missing children"}},{q="Where were the siblings last heard from?",a="They were last reported crossing the Stonetalon Mountains some weeks before Vahlarriel spoke to you.",al={"malem siblings last seen","where did they go","wagon route"}},{q="Why is Vahlarriel searching?",a="Their father fears the worst, and Vahlarriel has been charged with doing everything possible to find his missing children.",al={"who hired vahlarriel","who wants the siblings found"}},{q="What does Vahlarriel want you to find?",a="The wagon of Tyranis and Dalinda Malem in Desolace. If you find it, Vahlarriel asks you to come at once.",al={"how does vahlarriel search start","what is the first step"}}},kw={"chest","dalinda","darnassus","desolace","malem","stonetalon","tyranis","vahlarriel"},rel={"zone:desolace","zone:stonetalon","quest:1439","quest:1440"},m={start="Vahlarriel Demonslayer",["end"]="Malem Chest",level="33",faction="Alliance",id=1437},src={"Vahlarriel's Search"}}
E["quest:1438"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="After the second part of Vahlarriel's Search, Vahlarriel Demonslayer sends you to look for Dalinda and Tyranis Malem, beginning at the fortress. Word of it goes to Vahlarriel's superiors in Darnassus, who worry about Tyranis's motives and want Dalinda brought home safe above all.",h="After the second part of Vahlarriel's Search, Vahlarriel Demonslayer sends you to look for Dalinda and...",sec={{t="A Search at the Fortress",b="Vahlarriel Demonslayer wants you to look for both Dalinda and Tyranis, beginning at the fortress, and return with what you learn. Vahlarriel will contact superiors in Darnassus right away. A private word follows: they worry about why Tyranis came to Desolace, and they care most that Dalinda gets home safe. As for Tyranis, they want him gauged first, before any homecoming.",sp=0},{t="A Captive's Account",b="Dalinda, found in the large building facing the entrance, says the Burning Blade seized her and Tyranis and carried them here, and she believes she is to be sacrificed to their demon masters. She says the trip was a mistake from the start. Tyranis had grown hungry for arcane lore, against his people's wishes, and set out despite warnings of demons here. She dreads what has become of him.",sp=1}},faq={{q="Where is Dalinda Malem?",a="In the Thunder Axe Fortress area of Desolace, in the large building that faces the entrance.",al={"dalinda malem location","where to find dalinda","find dalinda desolace"}},{q="Who sends you to look for Dalinda and Tyranis?",a="Vahlarriel Demonslayer asks you to find both if you can, beginning at the fortress, while Vahlarriel informs superiors in Darnassus.",al={"who gives vahlarriel's search","quest giver vahlarriel","vahlarriel demonslayer quest"}},{q="Why does Darnassus care more about Dalinda than Tyranis?",a="Vahlarriel's superiors doubt Tyranis's reasons for coming to Desolace, and they value Dalinda's safe return above all.",al={"why is tyranis suspected","tyranis motives","why prioritize dalinda"}},{q="What came before this part of the search?",a="It follows the second part of Vahlarriel's Search.",al={"previous quest","prerequisite vahlarriel","vahlarriel search chain"}}},kw={"burning blade","dalinda","darnassus","demonslayer","desolace","malem","thunder axe fortress","tyranis","vahlarriel"},rel={"subzone:thunder-axe-fortress","zone:desolace","zone:darnassus","quest:1439","quest:1440","quest:1437","topic:elune"},m={start="Vahlarriel Demonslayer",["end"]="Dalinda Malem",level="33",faction="Alliance",id=1438},src={"Vahlarriel's Search (3)"}}
E["quest:1439"] = {t="quest",n="Search for Tyranis",z="desolace",s="Dalinda Malem tells you the orcs slaughtered all their guards and servants before bringing her and Tyranis here. Tyranis tried to speak to them, and she cannot leave until she knows what has become of her brother. She asks you to find him and come back when his fate is known.",h="Dalinda Malem tells you the orcs slaughtered all their guards and servants before bringing her and Tyranis...",sec={{t="A Brother Taken",b="Dalinda tells you that orcs killed every guard and servant of theirs before dragging her and Tyranis to this place. She expected to die at once, yet the orcs clearly had other designs. Tyranis tried talking to them, perhaps hoping his arcane learning would impress them, though she cannot say why. She will not escape until she knows his fate, so she asks you to find him and return when you do. He is in a building left of the fortress entrance.",sp=0},{t="Dalinda's Fear",b="Dalinda dreads that Tyranis, if allowed, will seek the Burning Blade's secrets and become one of them. Power has always drawn him, as it does anyone magic seduces. To her people even studying such things is a grave crime, and she doubts she could face her family with word that his spirit toyed with that danger.",sp=0},{t="What Dalinda Learns",b="When you come back, Dalinda calls it terrible but necessary. If your hand had not done it, her own people's would have. She asks pardon if her thanks sounds hollow. Knowing his fate, she is ready to escape and will accept your help if you are still willing.",sp=1}},faq={{q="Who is Tyranis Malem?",a="Dalinda's brother. He spoke to their captors, perhaps hoping to impress them with arcane learning, and she says the power of magic has always drawn him.",al={"who is tyranis","tyranis backstory","tyranis malem"}},{q="Why does Dalinda refuse to leave yet?",a="She will not leave until she knows what has happened to her brother. She asks you to find him and come back for her when his fate is known.",al={"why wont dalinda leave","why does dalinda stay","why wait to escape"}},{q="What happened to the guards and servants?",a="The orcs killed all of them, then took Dalinda and Tyranis alive, evidently with other plans.",al={"what happened to their guards","who was killed","guards and servants"}},{q="Where is Tyranis?",a="At Thunder Axe Fortress in Desolace, in the building on the left as you enter.",al={"where is tyranis","tyranis location"}},{q="What came before this step?",a="It follows the third part of Vahlarriel's Search, where Vahlarriel sent you to find Dalinda.",al={"what quest is before this","quest progression","vahlarriel quest chain"}}},kw={"burning blade","dalinda","desolace","malem","pendant","thunder axe fortress","tyranis","vahlarriel"},rel={"quest:1437","quest:1440","subzone:thunder-axe-fortress","zone:desolace"},m={start="Dalinda Malem",["end"]="Dalinda Malem",level="33",faction="Alliance",id=1439},src={"Search for Tyranis"}}
E["quest:1440"] = {t="quest",n="Return to Vahlarriel",z="desolace",s="Dalinda Malem is ready to leave Thunder Axe Fortress. She thanks you for what you have done for her and her family, and says the time is yours to choose. You escort her out, then find Vahlarriel Demonslayer.",h="Dalinda Malem is ready to leave Thunder Axe Fortress.",sec={{t="Leaving the Fortress",b="Dalinda asks whether the time has come, and offers thanks for all you have done for her and her family, in case things do not go as hoped. If you are ready, nothing else keeps her here, and she will go when you judge the moment right. You escort her out of Thunder Axe Fortress and then find Vahlarriel Demonslayer in Desolace.",sp=0},{t="Word from Vahlarriel",b="Vahlarriel thanks you. Dalinda reached Nijel's Point in far better shape than Vahlarriel could have asked for, and that she arrived on her own strength was a good sign. It pains Vahlarriel that neither sibling returned, but the embarrassment of Tyranis's choices is hers to endure once she is back in Darnassus.",sp=1}},faq={{q="Who asks you to escort her?",a="Dalinda Malem, who is ready to leave Thunder Axe Fortress when you judge the moment right.",al={"who gives return to vahlarriel","quest giver return to vahlarriel","who is dalinda malem"}},{q="Where does this begin?",a="At Thunder Axe Fortress in Desolace, where Dalinda is.",al={"dalinda malem location","where is dalinda malem","where does return to vahlarriel start"}},{q="Who do you go to after Dalinda is out?",a="Vahlarriel Demonslayer, in Desolace.",al={"where to turn in return to vahlarriel","who finishes return to vahlarriel","return to vahlarriel end"}},{q="What came before this step?",a="It follows Search for Tyranis, part of the longer Vahlarriel's Search.",al={"prereq return to vahlarriel","return to vahlarriel previous","what quest comes before return to vahlarriel"}}},kw={"dalinda malem","darnassus","desolace","escort","nijel's point","thunder axe fortress","tyranis","vahlarriel"},rel={"quest:1439","quest:1437","subzone:thunder-axe-fortress","subzone:nijel-s-point","zone:desolace","zone:darnassus"},m={start="Dalinda Malem",["end"]="Vahlarriel Demonslayer",level="33",faction="Alliance",id=1440},src={"Return to Vahlarriel"}}
E["quest:1454"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="Kreldig Ungor tells you of Karnitol, a mage who is some kind of noble in Stormwind. Sea giants struck his ship in the northwest waters of Desolace, and he left a valuable chest behind and teleported away. The chest and what is inside are to be found.",h="Kreldig Ungor tells you of Karnitol, a mage who is some kind of noble in Stormwind.",sec={{t="A Noble's Flight",b="After Reclaimers' Business in Desolace, Kreldig Ungor tells you of a first order of business. It concerns Karnitol, a mage who is some kind of noble in Stormwind. Sea giants struck Karnitol's ship in the northwest waters of Desolace. Karnitol and his servants tried to carry one of his costlier chests to shore, but the giants swarmed in, and he gave up the chest and teleported himself and his servants out. The chest and its contents are to be found, then returned to Karnitol in Stormwind. It lies along the northern coastline, in the Ethel Rethor stretch.",sp=0},{t="What the Chest Shows",b="The chest shows no water damage, but the lid has been forced open, and burn marks around the edges show that any magical traps guarding it were sprung long ago.",sp=1}},faq={{q="Who is Karnitol?",a="A mage who is some kind of noble in Stormwind. Sea giants struck his ship in the northwest waters of Desolace.",al={"karnitol","who is karnitol","who wants the chest"}},{q="What happened to Karnitol's ship?",a="Sea giants struck it in the northwest waters of Desolace. Karnitol and his servants tried to carry a valuable chest to shore, but the giants swarmed in, so he left the chest and teleported out with his servants.",al={"shipwreck story","why did ship sink","sea giant attack"}},{q="Who is looking for the chest?",a="Kreldig Ungor, who says Karnitol wants the chest and its contents found and returned to him in Stormwind.",al={"who gives quest","kreldig ungor role"}},{q="Where does the chest lie?",a="Along the northern coastline of Desolace, in the Ethel Rethor stretch.",al={"karnitol chest location","where is karnitol's chest","ethel rethor chest"}}},kw={"desolace","ethel rethor","karnitol","kreldig ungor","reclaimers","sea giants","shipwreck","stormwind"},rel={"npc:kreldig-ungor","subzone:ethel-rethor","zone:desolace","topic:stormwind-kingdom","topic:mage","quest:1453"},m={start="Kreldig Ungor",["end"]="Karnitol's Chest",level="39",faction="Alliance",id=1454},src={"The Karnitol Shipwreck"}}
E["quest:1455"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="The chest of the mage Karnitol has been pried open, and it is completely empty. Long, deep scratches on its sides and top suggest neither man nor giant was responsible, and you return to Kreldig Ungor at Nijel's Point.",h="The chest of the mage Karnitol has been pried open, and it is completely empty.",sec={{t="An Empty Chest",b="You study what forced the chest open. Long, deep scratches run along its sides and top. They point to something that was neither man nor giant, and they do not look like the work of a dagger or sword. The chest is completely empty. With nothing else to be done, you close it and prepare to leave, knowing Kreldig Ungor will be disappointed.",sp=0}},faq={{q="What is inside Karnitol's chest?",a="Nothing. The chest is completely empty.",al={"what was in karnitol chest","is karnitol chest empty","chest contents"}},{q="What made the marks on the chest?",a="Long, deep scratches run along the sides and top. They suggest neither man nor giant was responsible, and they do not look like the work of a dagger or sword.",al={"what opened the chest","who took the cargo","chest claw marks"}},{q="Who do you report to?",a="Kreldig Ungor, at Nijel's Point in Desolace.",al={"who do i turn this in to","where is kreldig ungor","where to go next"}},{q="What came before this?",a="The search for Karnitol's chest, which Kreldig Ungor asked of you.",al={"previous quest","karnitol shipwreck chain"}}},kw={"desolace","karnitol","karnitol's chest","kreldig ungor","nijel's point","shipwreck"},rel={"npc:kreldig-ungor","subzone:nijel-s-point","zone:desolace","quest:1454"},m={start="Karnitol's Chest",["end"]="Kreldig Ungor",level="39",faction="Alliance",id=1455},src={"The Karnitol Shipwreck (2)"}}
E["quest:1456"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="Kreldig Ungor still thinks Karnitol's belongings can be found. Up the same coast, by Ranazjar Isle, the Slitherblade naga hold a place among night elf ruins that lie at the bottom of the sea, and Kreldig reckons the satchel is most likely there.",h="Kreldig Ungor still thinks Karnitol's belongings can be found.",sec={{t="Ruins in the Deep",b="Following the second part of the Karnitol shipwreck search, Kreldig Ungor tells you hope is not lost. Along the same coast but farther north, close to Ranazjar Isle, sunken night elf ruins lie on the ocean floor, and the Slitherblade naga call them home. Kreldig judges it the likeliest place for Karnitol's satchel. A Recovery Diver's Potion is provided.",sp=0},{t="The Stronger Naga",b="Kreldig figures a scouting party that came so far south had to be a strong one. So in looking for Karnitol's belongings, Kreldig would try the more powerful naga first, the tidehunters and the sea witches.",sp=0}},faq={{q="Who asks you to find Karnitol's satchel?",a="Kreldig Ungor, in Desolace.",al={"who gives this quest","quest giver karnitol satchel","who is kreldig ungor"}},{q="Where does Kreldig think the belongings are?",a="Among the sunken night elf ruins north along the coast, near Ranazjar Isle, which the Slitherblade naga make their home.",al={"where is karnitol satchel","satchel location","where are the slitherblade naga"}},{q="Which naga does Kreldig suggest searching first?",a="The tidehunters and sea witches, the stronger naga. Kreldig reasons that a scouting party that went so far south would have been powerful.",al={"who has the satchel","which naga have it","tidehunter or sea witch"}},{q="What came before this?",a="The second part of the Karnitol shipwreck search comes before this.",al={"karnitol shipwreck quest chain","what quest comes before this"}}},kw={"desolace","karnitol","kreldig ungor","ranazjar isle","reclaimers","satchel","sea witch","slitherblade","tidehunter"},rel={"npc:kreldig-ungor","zone:desolace","topic:naga","topic:night-elf"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="39",faction="Alliance",id=1456},src={"The Karnitol Shipwreck (3)"}}
E["quest:1457"] = {t="quest",n="The Karnitol Shipwreck",z="desolace",s="Kreldig Ungor sends you to Ironforge with Karnitol's satchel, to put it in the hands of Roetten Stonehammer, who will pay you for the work.",h="Kreldig Ungor sends you to Ironforge with Karnitol's satchel, to put it in the hands of Roetten Stonehammer...",sec={{t="Back to Ironforge",b="Kreldig Ungor tells you to carry Karnitol's things back to Roetten Stonehammer in Ironforge, who will pay you for the work. With a laugh, Kreldig adds that Roetten may be so pleased that you get asked to join the Reclaimers full time. The way back should be made carefully and without dawdling, since Karnitol has little patience, though he is a generous man.",sp=0},{t="In Ironforge",b="Roetten Stonehammer greets the Karnitol business in Desolace with approval. The chest itself was wrecked, but everything that was in it is here, and Roetten leaves it to Karnitol to judge that. The Reclaimers are relied on to find what was lost, not to see that it returns looking fine and in good shape. Then Roetten sets about getting you paid.",sp=1}},faq={{q="Who do I deliver Karnitol's satchel to?",a="Roetten Stonehammer, in Ironforge.",al={"where do i take the satchel","turn in karnitol shipwreck","who gets karnitol's satchel"}},{q="Who sends me back to Ironforge?",a="Kreldig Ungor, who has praise for the job you did.",al={"who gives the quest","quest giver karnitol shipwreck part 4"}},{q="Why is it important to deliver the satchel quickly?",a="Kreldig says Karnitol has little patience, though he is very generous.",al={"why rush to ironforge","is karnitol patient"}},{q="Who is Roetten Stonehammer?",a="The Reclaimers' man in Ironforge. Business is booming for him, and he leaves smaller matters to his underlings.",al={"roetten stonehammer lore","who is roetten"}}},kw={"desolace","ironforge","karnitol","karnitol's satchel","kreldig ungor","reclaimers","roetten stonehammer"},rel={"npc:roetten-stonehammer","npc:kreldig-ungor","zone:ironforge","zone:desolace","quest:1456"},m={start="Kreldig Ungor",["end"]="Roetten Stonehammer",level="39",faction="Alliance",id=1457},src={"The Karnitol Shipwreck (4)"}}
E["quest:1458"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="Kreldig Ungor is gathering reagents for the gnome mage Leftwitch, who lives in Kharanos, and the Reclaimers are short-handed. He wants claws and horns from the Hatefury satyrs to the east before the rest of the list can begin.",h="Kreldig Ungor is gathering reagents for the gnome mage Leftwitch, who lives in Kharanos, and the Reclaimers...",sec={{t="Leftwitch's List",b="After Reclaimers' Business in Desolace, Kreldig Ungor has another job on his hands: fetching reagents for Leftwitch, the gnome mage who lives in Kharanos. Roetten reckons it is easy coin, since the Reclaimers are already out in Desolace, and Kreldig says he does not care that the crew is short-handed.",sp=0},{t="Horns and Claws",b="The first items on the list should be simple enough. Kreldig wants ten claws and ten horns taken from the Hatefury satyrs to the east, who are found in the Sargeron ruins due east of Nijel's Point. Once he has them, the rest of the list can begin.",sp=0}},faq={{q="Who is requesting these reagents?",a="Kreldig Ungor is collecting them for a gnome mage named Leftwitch, who lives in Kharanos. Roetten thinks it is easy coin, since the Reclaimers are already out in Desolace.",al={"who is leftwitch","reagents for reclaimers inc quest giver","who wants the reagents"}},{q="Where are the Hatefury satyrs located?",a="The Hatefury satyrs are found in the ruins of Sargeron, due east of Nijel's Point.",al={"hatefury satyr location","where are hatefury claws","hatefury horns location"}},{q="What does Kreldig want from the satyrs?",a="Ten Hatefury claws and ten Hatefury horns. With those in hand, he and you can move on to the next items on Leftwitch's list.",al={"what do i need to collect","reagents for reclaimers inc items","satyr parts needed"}},{q="What does Kreldig think about satyrs?",a="He calls them despicable creatures. He has heard they are linked in some way to the night elves, though he doubts it. In his view the story comes from the one elf who brought them into the war a few years back, and the world has been more dangerous and frightening since.",al={"kreldig satyr lore","are satyrs night elves"}}},kw={"desolace","hatefury","kharanos","kreldig ungor","leftwitch","reclaimers","roetten","sargeron","satyr"},rel={"quest:1453","npc:kreldig-ungor","subzone:sargeron","subzone:nijel-s-point","subzone:kharanos","topic:satyr","topic:gnome","zone:desolace"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="33",faction="Alliance",id=1458},src={"Reagents for Reclaimers Inc. (quest)"}}
E["quest:1459"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="Next on Leftwitch's list for Kreldig Ungor is venom from the scorpashi and hides from aged kodo. Kreldig cannot say where to find either, since he does not know Desolace well.",h="Next on Leftwitch's list for Kreldig Ungor is venom from the scorpashi and hides from aged kodo.",sec={{t="The Next Items",b="Following the first part of Leftwitch's list, Kreldig Ungor turns to the next items. They look simple enough, but the instructions are exact. The mage wants venom from the scorpashi, any of them will do, and hides from kodo, but only aged kodo. Dying and ancient kodo are no use. Kreldig wants seven vials of venom and three hides. Mages, Kreldig muses, ask for some odd things.",sp=0},{t="Unfamiliar Ground",b="Kreldig has no idea where the kodo and the scorpashi roam. Kreldig barely knows the area and has had no time to explore it.",sp=0}},faq={{q="Who is requesting these reagents?",a="Leftwitch, a mage, whose list Kreldig Ungor is working through.",al={"who wants reagents","who is leftwitch","kreldig boss"}},{q="Why does Kreldig need help finding these creatures?",a="Kreldig barely knows Desolace and has had no time to explore it, so cannot say where the kodo and the scorpashi roam.",al={"why cant kreldig get them","kreldig territory knowledge"}},{q="Can hides from any kodo be used?",a="No. Leftwitch's directions call for aged kodo only; dying and ancient ones do not count.",al={"any kodo hide","ancient kodo hide","dying kodo hide"}},{q="What are the scorpashi?",a="They are the scorpions found throughout Desolace. Leftwitch says venom from any of them will do.",al={"scorpashi venom","where are scorpashi"}},{q="Where do the aged kodo roam?",a="Herds of them follow the trails, chiefly in the south and west, and many end up near the Kodo Graveyard.",al={"aged kodo location","where are aged kodo"}}},kw={"aged kodo hide","desolace","ironforge","kreldig ungor","leftwitch","reclaimers inc","scorpashi venom"},rel={"quest:1458","npc:kreldig-ungor","zone:desolace","zone:ironforge","subzone:kodo-graveyard","topic:mage"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="35",faction="Alliance",id=1459},src={"Reagents for Reclaimers Inc. (2)"}}
E["quest:1465"] = {t="quest",n="Vahlarriel's Search",z="desolace",s="Going on with the search of the Malems' wagon, you turn up a pendant and a trail of footprints heading south. Smoke rises from a big fort far off. Vahlarriel Demonslayer at Nijel's Point should be shown the pendant and told about the sign that the Malems may live.",h="Going on with the search of the Malems' wagon, you turn up a pendant and a trail of footprints heading south.",sec={{t="Signs of Life",b="Searching the wagon further, you turn up a pendant, and beyond it footprints leading south. Far off, smoke rises from a big fort. A tended fire makes it, not buildings burning, and your instincts say that if the Malems are still alive, they were taken that way.",sp=0},{t="Word for Vahlarriel",b="Vahlarriel Demonslayer at Nijel's Point should see the Malem Pendant, and should hear of the footprints leading south.",sp=0},{t="What the Locals Say",b="Vahlarriel is furious at the whole affair. The two Malems were warned how dangerous Desolace is, and now both are missing, or worse. Hearing of the tracks toward the fort nearby, Vahlarriel calls it the best lead there is. By the locals' account, that fortress is overrun with the Burning Blade, orcs given over to demonic causes. They do not speak for most of the Horde, yet they are evil, and anyone caught spying on them will be killed on sight.",sp=1}},faq={{q="What did you find in the wagon?",a="A pendant, and footprints leading off to the south. In the distance, smoke rises from a large fort.",al={"what is in the chest","wagon clues","malem pendant"}},{q="Where do the tracks lead?",a="South, toward a large fort. The smoke over it is from a tended fire, not burning buildings, which suggests the Malems, should they be alive, were taken off in that direction.",al={"where did the footprints go","where is the fort","tracks direction"}},{q="Where is Vahlarriel Demonslayer located?",a="Vahlarriel Demonslayer is at Nijel's Point in Desolace. That is where the pendant and news of the tracks go.",al={"vahlarriel location","where to turn in malem pendant","vahlarriel demonslayer spot"}}},kw={"burning blade","demonslayer","desolace","fortress","malem","nijel's point","pendant","vahlarriel"},rel={"quest:1437","subzone:nijel-s-point","zone:desolace","topic:horde"},m={start="Malem Chest",["end"]="Vahlarriel Demonslayer",level="33",faction="Alliance",id=1465},src={"Vahlarriel's Search (2)"}}
E["quest:1466"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="Kreldig Ungor has the last of the items Leftwitch wants, and he admits it is not pretty and will take longer than the others. All of it comes from demons: brains, wings and vials of blood.",h="Kreldig Ungor has the last of the items Leftwitch wants, and he admits it is not pretty and will take longer...",sec={{t="The Last of the List",b="Kreldig warns that the final set is a grim business, slower to gather than any before it. Leftwitch wants three kinds of parts, ten of each. The brains come from felhounds: mana eaters, mage hunters or ley hunters. The wings come from the nether maidens, sisters or sorceresses. The blood comes from doomwarder captains or lords. Kreldig says he would understand if you passed on this one.",sp=0},{t="Demons in Desolace",b="Kreldig had not even realized these demons were in Desolace. From his reading, Desolace belonged mostly to the centaur once the night elves departed years ago, and he wonders how and why the demons settled here. They dwell near Mannoroc Coven, in Desolace's south, beyond the Kodo Graveyard.",sp=0}},faq={{q="Who is asking for these demon parts?",a="Kreldig Ungor passes along Leftwitch's list, and these demon parts are the last items on it.",al={"who gave this quest","who wants the demon parts","who is kreldig ungor"}},{q="What creatures hold the required items?",a="Felhound brains come from mana eaters, mage hunters and ley hunters. Wings come from the nether maidens, sisters and sorceresses. Blood comes from doomwarder captains and lords.",al={"what drops felhound brains","where to get nether wings","which doomwarders have blood"}},{q="Where can these demons be found?",a="They gather near Mannoroc Coven, at the southern end of Desolace, beyond the Kodo Graveyard.",al={"demon location","where is mannoroc coven","where do the demons roam"}},{q="Why does Kreldig find the demons surprising?",a="He had read that the centaur held Desolace once the night elves left years ago, so the demons' presence puzzles him.",al={"why are demons in desolace","centaur lore desolace"}}},kw={"desolace","doomwarder blood","felhound brain","kreldig ungor","leftwitch","mannoroc coven","nether wing","reclaimers inc"},rel={"npc:kreldig-ungor","zone:desolace","subzone:mannoroc-coven","subzone:kodo-graveyard","zone:ironforge","topic:centaur"},m={start="Kreldig Ungor",["end"]="Kreldig Ungor",level="40",faction="Alliance",id=1466},src={"Reagents for Reclaimers Inc. (3)"}}
E["quest:1467"] = {t="quest",n="Reagents for Reclaimers Inc.",z="desolace",s="Kreldig Ungor gives you Leftwitch's package and sends you back to Ironforge. Roetten Stonehammer is the one to see about your pay, and Kreldig promises a kind word about you once back home.",h="Kreldig Ungor gives you Leftwitch's package and sends you back to Ironforge.",sec={{t="Payment in Ironforge",b="Kreldig says your pay waits in Ironforge with Roetten Stonehammer himself. Roetten will be glad to be rid of Leftwitch's package, and handing it over should be enough to get what you are owed. Kreldig expects to be in Desolace only a little longer, and still means to speak well of you once home.",sp=0},{t="Roetten's Thanks",b="Roetten Stonehammer welcomes Leftwitch's package from Desolace and thanks you for the work and how quickly it was done. Your payment is ready, and Roetten remarks that a hard week's work is always well paid by Reclaimers Inc.",sp=1}},faq={{q="Who sends you back to Ironforge?",a="Kreldig Ungor sends you back to Ironforge with Leftwitch's package after the reagents are gathered.",al={"quest giver","who gives the quest","who starts this"}},{q="Where does Leftwitch's package need to go?",a="It goes to Roetten Stonehammer in Ironforge.",al={"where do i take the package","package destination","who gets the package"}},{q="Why do you carry the package to Roetten?",a="Kreldig says your pay comes from Roetten himself, so the package goes to him in Ironforge.",al={"why carry package","why visit roetten"}},{q="Is Kreldig Ungor remaining in Desolace?",a="Not for much longer, according to Kreldig, who still means to speak well of you once back home.",al={"does kreldig leave desolace","where is kreldig going"}}},kw={"desolace","ironforge","kreldig ungor","leftwitch's package","reagents for reclaimers inc","roetten stonehammer"},rel={"npc:roetten-stonehammer","npc:kreldig-ungor","zone:ironforge","zone:desolace","quest:1466"},m={start="Kreldig Ungor",["end"]="Roetten Stonehammer",level="40",faction="Alliance",id=1467},src={"Reagents for Reclaimers Inc. (4)"}}
E["quest:1480"] = {t="quest",n="The Corrupter",z="desolace",s="A piece of flayed demon skin, taken from the Burning Blade at Thunder Axe Fortress, smells rotten yet is surprisingly pliable. Red markings of some language cover one side, and at the bottom is a clear symbol that looks like a signature. Maurin Bonesplitter at Ghost Walker Post may be able to tell you more.",h="A piece of flayed demon skin, taken from the Burning Blade at Thunder Axe Fortress, smells rotten yet is...",sec={{t="A Strip of Skin",b="The torn skin stinks of rot, yet it bends easily, though it seems dry and fragile. Unrolled, it carries red markings on one side, a written language of some sort. At the bottom is a plain symbol, which you take to be a signature.",sp=0},{t="Maurin's View",b="Maurin Bonesplitter at Ghost Walker Post may know more about the skin. Maurin holds that the Burning Blade are coming to see how weak they are, with poor magic and little strength. Whatever power they have comes from those they serve, not from any grasp of true power and knowledge.",sp=0},{t="What the Markings Mean",b="Maurin recognises the runes as an old language, somewhat like Eredun but very different in the details. If Maurin is right, the skin is a contract of some kind, and the symbol at the bottom is the signature of a demon, Lord Azrethoc.",sp=1}},faq={{q="What is written on the flayed skin?",a="Red markings, a written language of some sort, cover one side. At the bottom is a clear symbol that looks like a signature. Maurin Bonesplitter at Ghost Walker Post may know more.",al={"flayed skin runes","what does the skin say","red markings on skin"}},{q="Where does the skin come from?",a="It is taken from the Burning Blade at Thunder Axe Fortress in Desolace.",al={"skin location","where to get demon skin","how to start the corrupter"}},{q="Who is Maurin Bonesplitter?",a="Maurin Bonesplitter is at Ghost Walker Post in Desolace, and that is where the skin is brought.",al={"where is maurin","maurin bonesplitter location","who is maurin"}},{q="What does Maurin think of the Burning Blade?",a="Maurin sees them as weak, with poor magic and little strength. In that view, whatever power they have comes from those they serve.",al={"maurin burning blade","burning blade power"}}},kw={"burning blade","eredun","flayed demon skin","ghost walker post","lord azrethoc","maurin bonesplitter","the corrupter","thunder axe fortress"},rel={"npc:maurin-bonesplitter","subzone:ghost-walker-post","subzone:thunder-axe-fortress","zone:desolace"},m={start="Flayed Demon Skin",["end"]="Maurin Bonesplitter",level="33",faction="Horde",id=1480},src={"The Corrupter"}}
E["quest:1481"] = {t="quest",n="The Corrupter",z="desolace",s="Maurin Bonesplitter believes the demon lord can be found, but first any wards the creature holds against scrying must be broken. For that, Maurin wants the scalp of a Hatefury shadowstalker, hunted in the old ruins of Desolace's northeast.",h="Maurin Bonesplitter believes the demon lord can be found, but first any wards the creature holds against...",sec={{t="Breaking the Wards",b="Maurin Bonesplitter believes the demon lord can be found, given the proper reagents. If the lord is as powerful as Maurin suspects, those must come from deadly creatures, and Maurin is sure you, acting in the Warchief's name, will take up the challenge. The first need is to break any wards the demon has against scrying. For that Maurin wants a scalp from a satyr, though only a Hatefury shadowstalker's will serve. They are to be sought in the old ruins of Desolace's northeast, near Sargeron.",sp=0},{t="The Right Scalp",b="Maurin cautions you against bringing back the wrong scalp. The wrong reagents could get people killed, since the demon lord may carry contingency spells meant to slay anyone who tries to scry on him. Maurin adds that fate has already dealt out enough pain.",sp=0},{t="When You Return",b="Maurin judges the scalp fit for his spell. While you were away he gathered some of the other reagents it needs, and he is almost ready. He lacks only a focus, an object to cast the demon lord's image and show where he is.",sp=1}},faq={{q="Who sends you to gather the scalp?",a="Maurin Bonesplitter asks for it, for a spell to find the demon lord.",al={"quest giver","who starts this","maurin bonesplitter"}},{q="Why does Maurin specifically need a Hatefury shadowstalker scalp?",a="Any wards the demon lord has against scrying must be broken first. For that Maurin needs the scalp of a satyr, and only a Hatefury shadowstalker's will do.",al={"why shadowstalker scalp","satyr scalp reason","why a satyr"}},{q="Where can the Hatefury shadowstalkers be found?",a="In the old ruins of Desolace's northeast, near Sargeron.",al={"where are shadowstalkers","shadowstalker location","satyr location"}},{q="What are the dangers of using the wrong reagents?",a="Maurin warns that the wrong reagents could cause deaths. The demon lord may carry contingency spells meant to slay anyone who tries to scry on him.",al={"why the right scalp","wrong reagents risk","contingency spells"}},{q="Where does this step fit into the search for the demon lord?",a="It follows the first part of The Corrupter, when you brought the flayed demon skin to Maurin.",al={"chain progression","quest order","what comes before this"}}},kw={"desolace","hatefury shadowstalker","maurin bonesplitter","sargeron","satyr","scrying","shadowstalker scalp","the corrupter"},rel={"quest:1480","npc:maurin-bonesplitter","subzone:sargeron","zone:desolace","topic:satyr"},m={start="Maurin Bonesplitter",["end"]="Maurin Bonesplitter",level="33",faction="Horde",id=1481},src={"The Corrupter (2)"}}
E["quest:1482"] = {t="quest",n="The Corrupter",z="desolace",s="Maurin Bonesplitter wants an oracle crystal, which the naga craft for their oracles, in order to find the demon lord Azrethoc. A vast coral reef lies northwest along the coast, home to the Slitherblade naga, and they will not welcome you.",h="Maurin Bonesplitter wants an oracle crystal, which the naga craft for their oracles, in order to find the...",sec={{t="An Oracle Crystal",b="Maurin Bonesplitter says an oracle crystal will do the job of finding the demon lord Azrethoc, whose signature was on the skin you brought. Naga craft such crystals, and their oracles use them. Up the coast to the northwest lies a vast coral reef which the naga have made their home while near the shore, and the oracles can be found in that place. The Slitherblade there are deadly and will take your intrusion badly, so Maurin urges you to go carefully and quickly.",sp=0},{t="A Shared Prize",b="Maurin points out that finding and destroying Lord Azrethoc would earn both of you much favor with the Warchief. Working together, and swiftly, would serve the ends of each.",sp=0}},faq={{q="Why does Maurin Bonesplitter need an oracle crystal?",a="He means to find the demon lord Azrethoc, and an oracle crystal is what he asks for to do it.",al={"why oracle crystal","what is the crystal for","maurin crystal purpose"}},{q="Where are the oracle crystals found?",a="The naga make them for their own oracles, and those oracles are in the vast coral reef northwest of Maurin, along the coast.",al={"where to find crystal","oracle crystal location","where are slitherblade oracles"}},{q="Who are the Slitherblade?",a="They are naga who have made a vast coral reef near the shore their home. Maurin calls them deadly and says they will take intruders badly.",al={"what are slitherblade","slitherblade naga","who lives in the reef"}},{q="Who is Azrethoc?",a="Azrethoc is the demon lord whose signature was on the skin you brought Maurin. Maurin wants to find and destroy him.",al={"who is azrethoc","demon lord azrethoc","what demon is maurin hunting"}},{q="What motivates Maurin to hunt this demon?",a="Maurin says finding and destroying Lord Azrethoc would earn both of you much favor with the Warchief.",al={"maurin motivation","why hunt azrethoc","warchief favor"}}},kw={"azrethoc","corrupter","desolace","maurin bonesplitter","naga","oracle crystal","slitherblade","warchief"},rel={"npc:maurin-bonesplitter","zone:desolace","topic:naga"},m={start="Maurin Bonesplitter",["end"]="Maurin Bonesplitter",level="35",faction="Horde",id=1482},src={"The Corrupter (3)"}}
E["quest:1484"] = {t="quest",n="The Corrupter",z="desolace",s="Maurin Bonesplitter has found the demon lord far more dangerous than expected. He is certain Takata Steelblade doubts his abilities, and leaving the swordsman uninformed of what happened would insult Takata's honor. Maurin sends you to speak with Takata, who is nearby.",h="Maurin Bonesplitter has found the demon lord far more dangerous than expected.",sec={{t="A Matter of Honor",b="Maurin Bonesplitter finds the creature much more dangerous than he had anticipated. No doubt Takata Steelblade questions whether Maurin can handle it, and not being told of what just happened would insult Takata's honor. Maurin asks you to speak to the swordsman and offer to slay the demon, should Takata allow it. Maurin cautions you not to press Takata too hard, since it is better if Takata believes the idea is his own.",sp=0},{t="Across the Path",b="Takata Steelblade is close at hand, just across the path from Maurin, on a cliff overlooking the Kodo Graveyard.",sp=0},{t="Takata's Answer",b="Takata witnessed what passed between Maurin and the demon lord. Even as an apparition, the creature seems to have more power than Maurin, Takata's warlock companion, and Takata wonders whether Maurin can defeat it. Takata going in person would serve the Warchief better, yet Takata's responsibilities here are such that leaving them to fight this evil for personal honor would disgrace the clan.",sp=1}},faq={{q="Why does Maurin Bonesplitter want Takata Steelblade told?",a="Maurin finds the demon lord far more dangerous than he expected. He is certain Takata doubts his abilities, and leaving the swordsman uninformed of what happened would insult Takata's honor.",al={"why talk to takata","maurin bonesplitter reason","why tell takata"}},{q="Where is Takata Steelblade located?",a="Close by, just across the path from Maurin, on a cliff overlooking the Kodo Graveyard in Desolace.",al={"takata location","where is takata","find takata steelblade"}},{q="Why does Maurin advise against pressing Takata too hard?",a="Maurin wants you to offer to slay the demon, if Takata allows it, without pressing hard. It is better if Takata believes the idea is his own.",al={"why not press takata","handling takata","takata pride"}}},kw={"demon lord","desolace","kodo graveyard","maurin bonesplitter","swordsman","takata steelblade","the corrupter"},rel={"npc:maurin-bonesplitter","npc:takata-steelblade","subzone:kodo-graveyard","zone:desolace","topic:warlock"},m={start="Maurin Bonesplitter",["end"]="Takata Steelblade",level="33",faction="Horde",id=1484},src={"The Corrupter (4)"}}
E["quest:1488"] = {t="quest",n="The Corrupter",z="desolace",s="Takata Steelblade knows nothing of Lord Azrethoc, yet sides with Maurin that the demon lord must be stopped, all the more if Azrethoc is trying to win influence over the Burning Blade. Takata trusts you to gather a party against Azrethoc and his warlock servant, Jugkar Grim'rod.",h="Takata Steelblade knows nothing of Lord Azrethoc, yet sides with Maurin that the demon lord must be stopped...",sec={{t="A Party to the South",b="Takata has never heard of Lord Azrethoc, yet agrees with Maurin that the demon lord must be stopped, above all if Azrethoc is reaching out to sway the Burning Blade. You have already shown you want to aid the Warchief, so Takata trusts you to gather a party and slay Azrethoc and his warlock servant, Jugkar Grim'rod. Takata tells you to head directly south, to Mannoroc Coven, where both are found.",sp=0},{t="Takata's Worry",b="Takata calls the demons in Desolace a greater threat than ever before. Each newly arrived foul creature makes the prospect of ever returning to the Warchief seem dimmer, and Takata sometimes wishes the centaur were the only enemy.",sp=0},{t="Takata's Verdict",b="Once the threat is ended, Takata calls it a mighty victory for all, and says the outlook here is less bleak than once feared. Takata speaks of the demons being slain, of the Burning Blade failing in their efforts, and of a place to call home that is safe again.",sp=1}},faq={{q="Who is sending adventurers against Lord Azrethoc?",a="Takata Steelblade, who sides with Maurin and trusts you to bring a party against the demon lord.",al={"who gives the corrupter","quest giver the corrupter","takata steelblade quest"}},{q="Who must be defeated?",a="Lord Azrethoc, a demon lord, and Jugkar Grim'rod, the warlock who serves him.",al={"who do i kill","corrupter targets","azrethoc and jugkar"}},{q="Where are the targets located?",a="Takata says to head directly south. Both are near Mannoroc Coven, which lies in southern Desolace.",al={"where is azrethoc","jugkar grimrod location","where to go the corrupter"}},{q="Why does Lord Azrethoc pose such a danger?",a="Takata has never heard of Azrethoc, but the demon lord must be stopped, all the more if Azrethoc is reaching out to sway the Burning Blade.",al={"why kill azrethoc","what is azrethoc doing","burning blade connection"}},{q="What comes before this in the chain?",a="This step follows the fourth part of The Corrupter chain.",al={"prerequisite quest","previous quest the corrupter","corrupter chain"}},{q="What does Takata fear about the demons in Desolace?",a="Takata calls them a greater threat than ever. Each newly arrived foul creature makes the prospect of returning to the Warchief seem dimmer, and Takata wishes the centaur were the only enemy.",al={"takata lore","why is takata here","takata steelblade role"}}},kw={"burning blade","demon","desolace","jugkar grim'rod","lord azrethoc","maurin","takata steelblade","warlock"},rel={"npc:takata-steelblade","zone:desolace","topic:horde","topic:warlock","topic:centaur","subzone:mannoroc-coven"},m={start="Takata Steelblade",["end"]="Takata Steelblade",level="40",faction="Horde",id=1488},src={"The Corrupter (5)"}}
E["quest:261"] = {t="quest",n="Down the Scarlet Path",z="desolace",s="Brother Anton of the Scarlet Crusade, at Nijel's Point, says his order is at war with the Scourge, an evil that corrupts the people and infects the land. He asks you to prove your allegiance by destroying thirty undead ravagers in the Valley of Bones.",h="Brother Anton of the Scarlet Crusade, at Nijel's Point, says his order is at war with the Scourge, an evil...",sec={{t="Proof of Allegiance",b="Brother Anton speaks bluntly. He says the Scourge must be halted before it swallows the land and pulls the world into darkness, and the Scarlet Crusade has pledged itself to that fight. If you are with them, he wants your courage and allegiance shown by destroying thirty undead ravagers. They are found south of Anton, in the Valley of Bones. Succeed, and the Crusade will welcome you.",sp=0}},faq={{q="Who asks you to destroy the undead ravagers?",a="Brother Anton of the Scarlet Crusade, at Nijel's Point.",al={"who gives down the scarlet path","brother anton quest","scarlet crusade desolace npc"}},{q="Where are the undead ravagers found?",a="The Valley of Bones, south of Nijel's Point in Desolace.",al={"undead ravager location","where is valley of bones","ravagers in desolace"}},{q="Why does Brother Anton want the ravagers destroyed?",a="He says the Crusade is at war with the Scourge, an evil that corrupts the people and infects the land, and he wants you to prove your allegiance.",al={"why kill undead ravagers","brother anton motive","scarlet crusade reason"}},{q="How many ravagers must be destroyed?",a="Thirty.",al={"how many ravagers","ravager count"}},{q="What comes before this?",a="Your meeting with Brother Anton comes first.",al={"previous quest","prerequisite for down the scarlet path"}}},kw={"brother anton","desolace","down the scarlet path","nijel's point","scarlet crusade","scourge","undead ravager","valley of bones"},rel={"quest:6141","topic:scarlet-crusade","subzone:nijel-s-point","subzone:valley-of-bones","zone:desolace","topic:scourge"},m={start="Brother Anton",["end"]="Brother Anton",level="39",faction="Alliance",id=261},src={"Down the Scarlet Path"}}
E["quest:5381"] = {t="quest",n="Hand of Iruxos",z="desolace",s="Taiga Wisemane in Shadowprey Village says the Burning Blade holds a Demon Box, and that something powerful called the Hand of Iruxos is kept inside. At Mannoroc Coven, the Burning Blade makes use of it to open demon portals. Taiga sends you to Thunder Axe Fortress to fetch the box.",h="Taiga Wisemane in Shadowprey Village says the Burning Blade holds a Demon Box, and that something powerful...",sec={{t="The Box in the Fortress",b="Taiga Wisemane wants the flow of demons into our world stopped. You are given a demon pick, to be used on the red crystal inside Thunder Axe Fortress, which opens the way to the Demon Box. The box and the pick are to be brought back to Taiga in Shadowprey Village.",sp=0}},faq={{q="Who asks for the Demon Box?",a="Taiga Wisemane, in Shadowprey Village.",al={"quest giver","who starts hand of iruxos","where to get quest"}},{q="What is the Hand of Iruxos?",a="Something powerful that lies inside the Demon Box. At Mannoroc Coven, the Burning Blade makes use of it to open portals for demons.",al={"what is hand of iruxos","hand of iruxos artifact","what does the hand do"}},{q="Where is the Demon Box?",a="In Thunder Axe Fortress, where a red crystal gives access to it.",al={"where is demon box","demon box location","find demon box"}},{q="How do you get to the Demon Box?",a="You are given a demon pick, and you use it on the red crystal inside Thunder Axe Fortress.",al={"how to get demon box","demon pick use","red crystal thunder axe"}}},kw={"burning blade","demon box","demon pick","hand of iruxos","mannoroc coven","red crystal","shadowprey village","taiga wisemane","thunder axe fortress"},rel={"npc:taiga-wisemane","quest:5581","subzone:thunder-axe-fortress","subzone:shadowprey-village","subzone:mannoroc-coven","zone:desolace"},m={start="Taiga Wisemane",["end"]="Taiga Wisemane",level="38",faction="Horde",id=5381},src={"Hand of Iruxos (quest)"}}
E["quest:5386"] = {t="quest",n="Catch of the Day",z="desolace",s="Cooked fish has not been smelled at Ghost Walker Post for a long time, and Nataka Longhorn would like that to change. Nataka rates the trolls of Shadowprey Village as the finest fish-catchers around, yet all the centaur activity leaves little time for the journey. You are asked to go in Nataka's place and bring back two Bloodbelly fish.",h="Cooked fish has not been smelled at Ghost Walker Post for a long time, and Nataka Longhorn would like that to...",sec={{t="A Taste of the Coast",b="No cooked fish has been smelled at Ghost Walker Post for a long while. Nataka Longhorn rates the trolls of Shadowprey Village as the finest fish-catchers, but with so much centaur activity there is little time to make the journey. So you are asked to go there, talk with the local fisherman Jinar'Zillen, and return with two Bloodbelly fish, Nataka's favorite. The road south of the post bends west and brings you to the troll village.",sp=0}},faq={{q="Who is looking for Bloodbelly fish?",a="Nataka Longhorn at Ghost Walker Post in Desolace. Bloodbelly fish are Nataka's favorite.",al={"who gives catch of the day","nataka longhorn quest"}},{q="Why can't Nataka Longhorn get the fish herself?",a="With so much centaur activity, Nataka has little time to make the journey to the trolls.",al={"why can't nataka leave","why does nataka need help"}},{q="Where can the Bloodbelly fish be found?",a="Nataka sends you to Shadowprey Village, a troll village, to speak with the local fisherman Jinar'Zillen.",al={"where to get bloodbelly fish","jinar'zillen location"}},{q="How do you reach Shadowprey Village from Ghost Walker Post?",a="The road south from the post leads west to the troll village.",al={"path to shadowprey village","how to get to troll village"}},{q="How many Bloodbelly fish does Nataka want?",a="Two.",al={"how many fish","bloodbelly fish count"}}},kw={"bloodbelly fish","catch of the day","centaur","desolace","ghost walker post","jinar'zillen","nataka longhorn","shadowprey village"},rel={"subzone:ghost-walker-post","subzone:shadowprey-village","quest:5421","zone:desolace","topic:troll","topic:centaur"},m={start="Nataka Longhorn",["end"]="Nataka Longhorn",level="37",faction="Horde",id=5386},src={"Catch of the Day"}}
E["quest:5421"] = {t="quest",n="Fish in a Bucket",z="desolace",s="Jinar'Zillen of Shadowprey Village in Desolace likes to do as little as possible. Many shellfish traps sit below the village docks, and anyone who gathers the shellfish from them will be repaid with something worth having.",h="Jinar'Zillen of Shadowprey Village in Desolace likes to do as little as possible.",sec={{t="Work Done by Someone Else",b="Jinar'Zillen keeps many shellfish traps below the docks of Shadowprey Village, and would far rather someone else did the collecting. Anyone willing to take on that work is promised something they want in return: one fine Bloodbelly fish for every five shellfish brought in.",sp=0}},faq={{q="Who offers this trade?",a="Jinar'Zillen, in Shadowprey Village in Desolace.",al={"who gives fish in a bucket","jinar'zillen","quest giver"}},{q="Where are the shellfish traps?",a="Below the docks of Shadowprey Village.",al={"trap location","where to find shellfish","shellfish traps"}},{q="Why does Jinar'Zillen want someone else to gather the shellfish?",a="Jinar'Zillen enjoys doing as little as possible, so anyone who collects from the traps is promised something in return.",al={"why does he need shellfish","jinar'zillen motive"}},{q="What does Jinar'Zillen give in return for the shellfish?",a="One fine Bloodbelly fish for every five shellfish.",al={"fish in a bucket reward","what do i get"}}},kw={"bloodbelly fish","desolace","fish in a bucket","jinar'zillen","shadowprey village","shellfish"},rel={"subzone:shadowprey-village","zone:desolace"},m={start="Jinar'Zillen",["end"]="Jinar'Zillen",level="25",faction="Horde",id=5421},src={"Fish in a Bucket"}}
E["quest:5501"] = {t="quest",n="Bone Collector",z="desolace",s="At Kormek's Hut in Desolace, the goblin Bibbly F'utzbuckle is certain that kodo bones are about to transform the world. Ten of them are wanted from the Kodo Graveyard, south of the hut, and something is promised in return.",h="At Kormek's Hut in Desolace, the goblin Bibbly F'utzbuckle is certain that kodo bones are about to transform...",sec={{t="Fortune in Old Bones",b="Bibbly insists the hut is sitting on a goldmine. Customers make furniture, musical instruments and even blasting powder from kodo bones. Bibbly sends you south to the Kodo Graveyard to bring back ten of them, with something promised in return.",sp=0},{t="A Caravan on the Way",b="A caravan comes by to pick up Bibbly's kodo bones, then sells them at Shadowprey Village. It is due any moment, and Bibbly is ten bones short of what is called a career high.",sp=0},{t="Bibbly's Big Dreams",b="When the bones arrive, Bibbly pictures the chaps back home seeing Bibbly's face splashed across Goblin'preneur, and imagines being the richest goblin in the world. Bibbly also recalls a physical education teacher who said Bibbly would never amount to anything.",sp=1}},faq={{q="Who is Bibbly F'utzbuckle?",a="Bibbly F'utzbuckle is a goblin at Kormek's Hut in Desolace, convinced that kodo bones are a goldmine and wanting ten more of them.",al={"who gives bone collector","bibbly futzbuckle","kormek hut goblin"}},{q="Why does Bibbly need kodo bones?",a="Bibbly has customers who turn kodo bones into furniture, musical instruments and even blasting powder.",al={"what are kodo bones used for","why kodo bones"}},{q="Where do the kodo bones go after Bibbly gets them?",a="A caravan stops by to collect Bibbly's kodo bones, then sells them in Shadowprey Village.",al={"where do the bones go","caravan destination"}},{q="Where can the kodo bones be found?",a="Bibbly sends you to the Kodo Graveyard, which lies south of Kormek's Hut in Desolace.",al={"kodo bone location","where to find kodo bones"}},{q="Where is Kormek's Hut?",a="Kormek's Hut is in Desolace, north of the Kodo Graveyard.",al={"kormeks hut location","where is bibbly"}}},kw={"bibbly f'utzbuckle","bone collector","desolace","goblin'preneur","kodo bone","kodo graveyard","kormek's hut","shadowprey village"},rel={"subzone:kodo-graveyard","subzone:kormek-s-hut","subzone:shadowprey-village","zone:desolace","topic:goblin"},m={start="Bibbly F'utzbuckle",["end"]="Bibbly F'utzbuckle",level="39",faction="Neutral",id=5501},src={"Bone Collector"}}
E["quest:5561"] = {t="quest",n="Kodo Roundup",z="desolace",s="At Scrabblescrew's Camp in Desolace, Smeed Scrabblescrew is expecting a caravan and wants five tamed kodos ready for it. You carry Smeed's kodo kombobulator out among the ancient, aged and dying kodos, and lead the ones it tames back to the camp.",h="At Scrabblescrew's Camp in Desolace, Smeed Scrabblescrew is expecting a caravan and wants five tamed kodos...",sec={{t="A Caravan on Its Way",b="Bibbly believes no other goblin in Desolace knows how to turn a profit. Smeed Scrabblescrew disagrees: the one caravan willing to brave this land depends on Smeed, and Smeed has formed a partnership with Cork and Rigger. The caravan is due at the camp shortly.",sp=0},{t="The Kodo Kombobulator",b="Smeed built a device that can rejuvenate and bring under control aged and dying kodos. Aimed at an ancient, aged or dying kodo, it jolts the beast into a tamed kodo that follows you. You bring five of them back to Scrabblescrew's Camp, along with the device.",sp=0}},faq={{q="Who is Smeed Scrabblescrew?",a="Smeed Scrabblescrew is found at Scrabblescrew's Camp in Desolace. Smeed invented the kodo kombobulator and has a partnership with Cork and Rigger. Bibbly thinks no other goblin in Desolace knows how to make money, and Smeed does not agree.",al={"who is smeed","smeed scrabblescrew lore","scrabblescrew"}},{q="Why does Smeed need tamed kodos?",a="The caravan that relies on Smeed is due at the camp shortly, and Smeed is waiting on five newly tamed kodos.",al={"why tame kodos","kodo roundup purpose","why does smeed want kodos"}},{q="What is the Kodo Kombobulator?",a="It is Smeed's invention, made to revive and bring under control kodos that are aged or dying. Used on one, it jolts the beast into a tamed kodo that follows you.",al={"what does kombobulator do","kodo kombobulator lore"}},{q="Which kodos can you use the kombobulator on?",a="Ancient, aged and dying kodos. Once one is tamed, it follows you back to Scrabblescrew's Camp.",al={"which kodos to tame","kodo roundup kodos"}},{q="Who is Bibbly?",a="Bibbly is a goblin in Desolace who thinks no other goblin there knows how to make money. Smeed Scrabblescrew has a different view.",al={"bibbly rival","who is bibbly"}}},kw={"bibbly","cork","desolace","kodo","kodo kombobulator","rigger","scrabblescrew's camp","smeed scrabblescrew"},rel={"zone:desolace","topic:goblin"},m={start="Smeed Scrabblescrew",["end"]="Smeed Scrabblescrew",level="34",id=5561},src={"Kodo Roundup"}}
E["quest:5581"] = {t="quest",n="Portals of the Legion",z="desolace",s="After Hand of Iruxos, Taiga Wisemane in Shadowprey Village shows you the Hand and asks you to banish six demon portals at Mannoroc Coven, warning you to be wary of the portal guardians.",h="After Hand of Iruxos, Taiga Wisemane in Shadowprey Village shows you the Hand and asks you to banish six...",sec={{t="Closing the Gates",b="Taiga Wisemane holds up the Hand of Iruxos, a grisly thing to look at, and says you must carry it if the demon portals around Mannoroc Coven are ever to be closed. The demon threat is increasing, and shutting the portals will check the number of demons crossing into this world. She wants all six portals banished, and she warns you to be wary of their guardians.",sp=0}},faq={{q="Where are the demon portals?",a="At Mannoroc Coven in Desolace.",al={"portal location","where is mannoroc coven","where are the legion portals"}},{q="What is needed to banish the portals?",a="The Hand of Iruxos. Taiga Wisemane says you must possess it for the portals to be banished.",al={"how to banish portals","what item closes portals","hand of iruxos use"}},{q="Who asks you to banish the portals?",a="Taiga Wisemane, in Shadowprey Village.",al={"quest giver","who gives portals of the legion","taiga wisemane location"}},{q="How many portals must be banished?",a="Six, at Mannoroc Coven.",al={"how many portals","portal count"}},{q="What came before this?",a="Hand of Iruxos, in which Taiga Wisemane sent you to Thunder Axe Fortress for the Demon Box.",al={"previous quest","prereq","prerequisite"}}},kw={"demon portals","desolace","hand of iruxos","legion","mannoroc coven","shadowprey village","taiga wisemane"},rel={"quest:5381","npc:taiga-wisemane","subzone:mannoroc-coven","subzone:shadowprey-village","zone:desolace"},m={start="Taiga Wisemane",["end"]="Taiga Wisemane",level="38",faction="Horde",id=5581},src={"Portals of the Legion (Classic)"}}
E["quest:5741"] = {t="quest",n="Sceptre of Light",z="desolace",s="Azore Aldamort has heard that the Burning Blade of Thunder Axe Fortress, to the east, now hold the Sceptre of Light, which word says they obtained from the naga. Legend says it could sink whole cities beneath the great seas, and Azore will not let the Burning Blade keep such power. You are asked to bring it back to Ethel Rethor.",h="Azore Aldamort has heard that the Burning Blade of Thunder Axe Fortress, to the east, now hold the Sceptre of...",sec={{t="A Sceptre of the Naga",b="Word has it that the naga's Sceptre of Light has come into the hands of the Burning Blade at Thunder Axe Fortress. Legend says it can sink whole cities beneath the great seas. Azore Aldamort holds that the Burning Blade cannot be allowed such power.",sp=0},{t="The Seer's Tower",b="A Burning Blade seer keeps the sceptre and studies it from the top of one of the fortress watchtowers. Azore wants you to take it from there yourself and carry it back to the tower at Ethel Rethor.",sp=0}},faq={{q="What power does the Sceptre of Light possess?",a="Legend says it can sink whole cities beneath the great seas. Word is that it came to the Burning Blade from the naga.",al={"what does sceptre of light do","sceptre of light lore","how powerful is sceptre of light"}},{q="Who currently holds the Sceptre of Light?",a="A Burning Blade seer, who keeps it in one of the watchtowers of Thunder Axe Fortress and studies it there.",al={"who has the sceptre of light","where is sceptre of light","who drops sceptre of light"}},{q="Who asks for the Sceptre of Light?",a="Azore Aldamort, of the tower at Ethel Rethor.",al={"who gives sceptre of light","where to pick up sceptre of light"}},{q="How did the Burning Blade get the sceptre?",a="Word is that they obtained it from the naga.",al={"how did burning blade get the sceptre","burning blade naga connection"}}},kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","sceptre of light","seer","thunder axe fortress"},rel={"subzone:ethel-rethor","subzone:thunder-axe-fortress","quest:6027","topic:naga","zone:desolace"},m={start="Azore Aldamort",["end"]="Azore Aldamort",level="33",faction="Neutral",id=5741},src={"Sceptre of Light (quest)"}}
E["quest:5763"] = {t="quest",n="Hunting in Stranglethorn",z="desolace",s="Roon Wildmane, a tauren in Desolace, once hunted beside a dwarf named Hemet. Now Roon sends you off with a kodo horn, bound for Hemet Nesingwary in Stranglethorn, north of Grom'gol Base Camp.",h="Roon Wildmane, a tauren in Desolace, once hunted beside a dwarf named Hemet.",sec={{t="A Token Between Hunters",b="Long ago a dwarf named Hemet came to Desolace, eager to hunt great beasts. Hemet handled a rifle with uncanny skill, and the two hunters passed many days together, the old enmity between their peoples set aside. When Hemet went off to Stranglethorn, Roon vowed to welcome Hemet back one day for another hunt, and Roon decides that time has arrived. You are to carry Roon's kodo horn to Hemet, who will know whose it is. Look in Stranglethorn, north of Grom'gol Base Camp.",sp=0},{t="Hemet's Answer",b="Hemet knows the horn at once for the tauren Roon Wildmane's, and recalls the good hunting they shared among the beasts of Desolace. Hemet is neck deep in the jungle for now, but thanks you, and thinks the next expedition may lead back to Desolace, where the centaurs live.",sp=1}},faq={{q="Who is Hemet?",a="A dwarf who came to Desolace wishing to hunt great beasts. Hemet's rifle skill was uncanny, and Hemet and Roon Wildmane hunted together for many days before Hemet left for Stranglethorn.",al={"hemet nesingwary","who is hemet"}},{q="Why does Roon Wildmane care about a dwarf?",a="The two hunted together for many days, and the enmity between their peoples was forgotten. Roon vowed to welcome Hemet back so they could hunt again.",al={"why help dwarf","roon wildmane dwarf friend"}},{q="Where is Hemet located?",a="In Stranglethorn, north of Grom'gol Base Camp.",al={"where is hemet","hemet location","stranglethorn hunting camp"}},{q="What is the purpose of the kodo horn?",a="Roon Wildmane sends it to Hemet, who will know it is from Roon.",al={"kodo horn purpose","why deliver kodo horn"}}},kw={"desolace","grom'gol","hemet nesingwary","kodo horn","roon wildmane","stranglethorn"},rel={"zone:desolace","subzone:grom-gol-base-camp","topic:tauren","topic:dwarf","topic:centaur"},m={start="Roon Wildmane",["end"]="Hemet Nesingwary",level="31",faction="Horde",id=5763},src={"Hunting in Stranglethorn"}}
E["quest:5821"] = {t="quest",n="Bodyguard for Hire",z="desolace",s="Cork Gizelton and Rigger would normally lead their kodo past the Kolkar centaur village, yet they stop whenever the centaur war drums are heard. Cork asks you to protect the caravan past the Kolkar village, and payment is waiting with Smeed Scrabblescrew, a bit down the road.",h="Cork Gizelton and Rigger would normally lead their kodo past the Kolkar centaur village, yet they stop...",sec={{t="War Drums",b="Cork Gizelton and Rigger would normally take their kodo straight past the Kolkar centaur. Now and then the centaur war drums are heard, and the caravan stops, because dead traders make no profit. Cork asks you to guard the caravan past the Kolkar village, a short distance, and keep it in one piece. The caravan waits north of the Kolkar Village and southeast of Thunder Axe Fortress.",sp=0},{t="Smeed Scrabblescrew",b="Payment waits with Smeed Scrabblescrew at Scrabblescrew's Camp, a bit down the road. Smeed does a little business with the Gizelton caravan.",sp=0}},faq={{q="Who is Cork Gizelton?",a="Cork Gizelton leads a kodo caravan through Desolace together with Rigger. The two of them stop whenever the centaur war drums sound.",al={"cork gizelton","who gives bodyguard for hire","who starts this"}},{q="Why does the caravan need protection?",a="Cork and Rigger stop whenever the centaur war drums sound, because dead traders make no profit.",al={"why need bodyguard","why caravan stopped","why are they waiting"}},{q="Where does this escort start?",a="North of the Kolkar Village, and southeast of Thunder Axe Fortress.",al={"bodyguard for hire location","where does caravan start","escort start point"}},{q="Where is the payment waiting?",a="With Smeed Scrabblescrew at Scrabblescrew's Camp, a bit down the road. Smeed does a little business with Cork.",al={"who gives the reward","where do i turn in","who is smeed"}}},kw={"bodyguard","centaur","cork gizelton","desolace","gizelton caravan","kolkar","rigger","smeed scrabblescrew"},rel={"zone:desolace","topic:centaur","subzone:thunder-axe-fortress"},m={start="Cork Gizelton",["end"]="Smeed Scrabblescrew",level="35",faction="Neutral",id=5821},src={"Bodyguard for Hire"}}
E["quest:5943"] = {t="quest",n="Gizelton Caravan",z="desolace",s="Rigger Gizelton and Cork launched their caravan to get rich, and found the trade more dangerous than they expected. Mannoroc Coven lies ahead, and Rigger wants a capable adventurer to guard the caravan past it.",h="Rigger Gizelton and Cork launched their caravan to get rich, and found the trade more dangerous than they...",sec={{t="Past Mannoroc Coven",b="Rigger Gizelton and Cork set up the caravan to make a fortune, and had no idea how risky turning a profit could be. Mannoroc Coven lies ahead. The demons usually leave the caravan alone, but this time the kodos are spooked. Rigger offers payment if you protect the caravan past the coven. Once it is safely through, your pay waits with Smeed, a business associate of theirs, at Scrabblescrew's Camp.",sp=0},{t="Smeed's Misgivings",b="At Scrabblescrew's Camp, Smeed wipes his brow and says he would be ruined if the caravan ever vanished, so he is glad to hear it is not lost. He is not sure it makes sense to pay so much to protect a caravan whose owners earn only one gold piece a week. Still, as long as Cork and Rigger keep paying for his kodos, he does not care how they run their business.",sp=1}},faq={{q="Who is Rigger Gizelton?",a="A caravan owner who started the Gizelton Caravan with Cork, hoping to make a fortune.",al={"who is rigger","gizelton background","rigger gizelton"}},{q="Why does the caravan need protection past Mannoroc Coven?",a="Rigger says the demons there usually ignore the caravan, but this time something has the kodos spooked.",al={"why escort caravan","mannoroc coven danger","why protect caravan"}},{q="Who pays you for protecting the caravan?",a="Smeed, the Gizeltons' business associate at Scrabblescrew's Camp, once the caravan is safely past the coven.",al={"who pays me","where to turn in gizelton caravan","smeed reward"}},{q="Who is Cork?",a="Rigger Gizelton's partner in the caravan.",al={"cork gizelton","who is cork"}}},kw={"caravan","cork","coven","desolace","gizelton","kodo","mannoroc","rigger","scrabblescrew","smeed"},rel={"subzone:mannoroc-coven","quest:5821","zone:desolace"},m={start="Rigger Gizelton",["end"]="Smeed Scrabblescrew",level="38",faction="Neutral",id=5943},src={"Gizelton Caravan (quest)"}}
E["quest:6027"] = {t="quest",n="Book of the Ancients",z="desolace",s="Azore Aldamort of the Ethel Rethor tower trusts you with a gem. Set in the hand of a serpent statue on Ranazjar Isle, northwest of the tower, it calls up the protector of the Book of the Ancients, which holds secrets the naga have kept for centuries.",h="Azore Aldamort of the Ethel Rethor tower trusts you with a gem.",sec={{t="The Serpent Statue",b="After Sceptre of Light, Azore Aldamort hands you the Gem of the Serpent. A Serpent Statue stands on Ranazjar Isle, a little island to the northwest of the Ethel Rethor tower, and the gem belongs on its hand. That will bring forth the guardian of the Book of the Ancients, a book that holds naga secrets kept for centuries. Azore hopes it will teach much about their scaled foes.",sp=0}},faq={{q="Who is Azore Aldamort?",a="The keeper of the tower at Ethel Rethor, who hopes to learn much about the naga, whom Azore calls scaled foes.",al={"azore aldamort","who gives book of the ancients","tower in ethel rethor guy"}},{q="What is the Book of the Ancients?",a="A book containing the secrets of the naga, kept for centuries. Someone guards it.",al={"what is the book of the ancients","book lore","naga book desolace"}},{q="Where is Ranazjar Isle?",a="A small island northwest of the Ethel Rethor tower.",al={"ranazjar isle location","where is ranazjar isle","where do i go with the gem"}},{q="What is the Gem of the Serpent for?",a="Set on the hand of the Serpent Statue on Ranazjar Isle, it brings forth the guardian of the Book of the Ancients.",al={"gem of the serpent","serpent statue hand","how to summon guardian"}},{q="What came before this?",a="Sceptre of Light, which comes before this step.",al={"previous quest","sceptre of light chain","prerequisite"}}},kw={"azore aldamort","book of the ancients","ethel rethor","gem of the serpent","naga","ranazjar isle","serpent statue"},rel={"quest:5741","subzone:ethel-rethor","topic:naga","zone:desolace"},m={start="Azore Aldamort",["end"]="Azore Aldamort",level="38",id=6027},src={"Book of the Ancients (quest)"}}
E["quest:6132"] = {t="quest",n="Get Me Out of Here!",z="desolace",s="Melizza Brimbuzzle traveled into the Valley of Spears hoping to do business with the Maraudines, but they would not talk, and she fears they mean to eat her. She asks you to get her out of there; her brother Hornizz will pay you handsomely.",h="Melizza Brimbuzzle traveled into the Valley of Spears hoping to do business with the Maraudines, but they...",sec={{t="Trouble in the Valley",b="Melizza walked into the Valley of Spears to speak with the Maraudines, thinking she could strike a deal. They would not talk, and she suspects they would rather eat her. She says she overheard centaurs only minutes ago discussing wood for their cookpot, and she wants out quickly.",sp=0},{t="Her Brother's Camp",b="Hornizz Brimbuzzle waits at the family camp, east of here and beside the kodo graveyard. Melizza promises that her brother will pay you well for bringing her out of the valley.",sp=0},{t="Back at the Camp",b="Hornizz says Melizza told him you were coming, and thanks you for getting her out of her jam. He guesses she has already found herself a new one. Melizza dashes ahead, calls the Maraudines too hard to work with, and says she is off to the Gelkis, who are more reasonable.",sp=1}},faq={{q="Why is Melizza Brimbuzzle in trouble?",a="Melizza walked into the Valley of Spears hoping to do business with the Maraudines. They would not talk, and she thinks they want to eat her.",al={"why is melizza captured","melizza brimbuzzle story","what happened to melizza"}},{q="Who are the Maraudines?",a="The Maraudines are centaurs of Desolace. The Valley of Spears is where Melizza went to try to do business with them.",al={"maraudine centaur","who are maraudines","maraudine clan"}},{q="Where is Hornizz Brimbuzzle located?",a="Hornizz Brimbuzzle waits at the Brimbuzzles' camp in Desolace, next to the Kodo Graveyard, eastward.",al={"hornizz location","where is hornizz","hornizz brimbuzzle camp"}},{q="Why does Melizza say her brother will pay you?",a="She promises that her brother Hornizz will pay you handsomely if you see her out of the valley.",al={"melizza reward","what does hornizz pay"}}},kw={"centaur","desolace","hornizz brimbuzzle","kodo graveyard","maraudine","melizza brimbuzzle","valley of spears"},rel={"subzone:valley-of-spears","subzone:kodo-graveyard","topic:centaur","zone:desolace"},m={start="Melizza Brimbuzzle",["end"]="Hornizz Brimbuzzle",level="39",id=6132},src={"Get Me Out of Here!"}}
E["quest:6134"] = {t="quest",n="Ghost-o-plasm Round Up",z="desolace",s="Hornizz Brimbuzzle thinks there is money in the ghosts of the Valley of Bones. He figures the Magram centaurs would pay plenty for ghost energy, and he gives you a crate of ghost magnets to draw the spirits out.",h="Hornizz Brimbuzzle thinks there is money in the ghosts of the Valley of Bones.",sec={{t="A Haunted Valley",b="Hornizz points you southeast, to the Valley of Bones, where Magram ghosts walk. It sounds frightening, he admits, but surely it is scarier still for the Magram. He is sure that ghost energy captured there would be worth plenty to those centaurs.",sp=0},{t="Between the Dead Goliaths",b="He hands you a crate of ghost magnets. Set down between the two huge skeletons in the valley, known as the Dead Goliaths, a magnet lures the ghosts toward it. From them you take ghost-o-plasm, which is what Hornizz plans to sell to the Magram. He wants eight ghost-o-plasms brought back to him, along with the crate.",sp=0},{t="Back with the Haul",b="When you return, Hornizz notices that some of the ghost-o-plasm has rubbed off on you, and he calls it slimy. He reckons it a fortune in the making, provided the centaurs can be persuaded of what it is.",sp=1}},faq={{q="Who is Hornizz Brimbuzzle?",a="Hornizz Brimbuzzle keeps a camp just southwest of the Kodo Graveyard in Desolace. He wants to sell ghost energy to the Magram centaurs.",al={"hornizz","brimbuzzle","who gives ghost-o-plasm round up"}},{q="Where is the Valley of Bones?",a="Hornizz places the Valley of Bones to the southeast. The two Dead Goliaths, the big skeletons where the magnet is set, stand at its southern end.",al={"valley of bones location","where do i find the ghosts","dead goliaths location"}},{q="Why does Hornizz want ghost-o-plasm?",a="He is sure the Magram centaurs would pay plenty for ghost energy captured in the haunted Valley of Bones, and ghost-o-plasm is what he means to sell them.",al={"why collect ghost energy","who buys ghost-o-plasm","centaur ghost plasma"}},{q="How does the ghost magnet work?",a="A magnet placed between the two Dead Goliaths draws the valley's ghosts toward it, and the ghosts yield ghost-o-plasm.",al={"how to use ghost magnet","where to place ghost magnet","attracting magram ghosts"}}},kw={"dead goliaths","desolace","ghost magnet","ghost-o-plasm","hornizz brimbuzzle","magram","spectres","valley of bones"},rel={"zone:desolace","subzone:valley-of-bones","subzone:kodo-graveyard","subzone:mannoroc-coven","topic:centaur"},m={start="Hornizz Brimbuzzle",["end"]="Hornizz Brimbuzzle",level="39",faction="Neutral",id=6134},src={"Ghost-o-plasm Round Up"}}
E["quest:6141"] = {t="quest",n="Brother Anton",z="desolace",s="Brother Crowley speaks of Brother Anton, a fellow warrior who learned of undead in distant Kalimdor and booked passage at once to destroy them. Anton is looking for people with bravery and resolve, and waits in Nijel's Point in Desolace.",h="Brother Crowley speaks of Brother Anton, a fellow warrior who learned of undead in distant Kalimdor and...",sec={{t="A Brother Abroad",b="Brother Crowley says rumors of an undead infestation in Desolace, a land in far-off Kalimdor, reached Anton, who immediately booked passage to seek and destroy the menace. Anton wants help from those with bravery and resolve. If your heart is true, Crowley tells you to speak with Anton in Nijel's Point, the Alliance town in Desolace.",sp=0},{t="Word from the East",b="Brother Anton has already received word that aid is arriving from the east. He asks whether you are the source of those rumors, and whether you have come to help with the crusade of the Scarlet Brother.",sp=1}},faq={{q="Who is Brother Anton?",a="Brother Anton is the brother in arms of Brother Crowley. He heard that undead were infesting Desolace and booked passage there to destroy them.",al={"who is anton","brother anton lore","anton desolace"}},{q="Where can Brother Anton be found?",a="Brother Anton is in Nijel's Point, the Alliance town in Desolace.",al={"where is brother anton","anton location","brother anton spot"}},{q="Why did Brother Anton go to Kalimdor?",a="Rumors of undead infesting Desolace, in Kalimdor, reached him, and he booked passage straight away to destroy them.",al={"why is anton in desolace","anton mission desolace","why did anton travel"}}},kw={"brother anton","brother crowley","desolace","nijel's point","scarlet","undead"},rel={"quest:261","subzone:nijel-s-point","zone:desolace","topic:alliance"},m={start="Brother Crowley",["end"]="Brother Anton",level="39",faction="Alliance",id=6141},src={"Brother Anton (quest)"}}
E["quest:6142"] = {t="quest",n="Clam Bait",z="desolace",s="Mai'Lahii at Shadowprey Village has fished all his life and says the best bait is soft-shelled clam meat, which no fish can resist. He wants ten pieces, to be found around a wrecked ship up the coast to the north.",h="Mai'Lahii at Shadowprey Village has fished all his life and says the best bait is soft-shelled clam meat...",sec={{t="The Best Bait",b="Mai'Lahii has fished all his life, and he swears by soft-shelled clam meat as bait, since the fish cannot resist it. To the north, off the coast, lies a wrecked ship, and soft-shelled clams are scattered throughout that area. He asks for ten pieces of the meat.",sp=0},{t="What Mai'Lahii Says",b="Mai'Lahii says the witch doctor gave him exactly this advice for his headache: go fish, and he will feel better. He feels better already.",sp=1}},faq={{q="Who is Mai'Lahii?",a="Mai'Lahii is a fisherman in Shadowprey Village on the Desolace coast. He has fished all his life.",al={"mailahii","who asks for clam bait","fisherman in shadowprey"}},{q="Where can the soft-shelled clams be found?",a="North of Shadowprey Village, around the wreck of a ship lying off the coast, where soft-shelled clams are scattered.",al={"clam bait location","where is the shipwreck","soft-shelled clam meat location"}},{q="Why does Mai'Lahii want clam meat?",a="He says soft-shelled clam meat is the best bait there is, and the fish cannot resist it.",al={"why clam bait","why clam meat"}},{q="How much clam meat does Mai'Lahii want?",a="Ten pieces of the clam meat.",al={"how many clams","clam meat amount"}}},kw={"clam bait","desolace","fishing bait","mai'lahii","shadowprey village","shipwreck","soft-shelled clam"},rel={"subzone:shadowprey-village","zone:desolace"},m={start="Mai'Lahii",["end"]="Mai'Lahii",level="35",faction="Horde",id=6142},src={"Clam Bait"}}
E["quest:6143"] = {t="quest",n="Other Fish to Fry",z="desolace",s="Drulzegar Skraghook, a fisherman at Shadowprey Village in Desolace, lost the entire crew to the naga while fishing near Ranazjar Isle. Guilt weighs on Drulzegar, who asks you to go after the Slitherblade.",h="Drulzegar Skraghook, a fisherman at Shadowprey Village in Desolace, lost the entire crew to the naga while...",sec={{t="A Crew Lost",b="Drulzegar Skraghook and the crew fished by Ranazjar Isle, which lies north of a wreck on the coast, and had done so many times. One morning the naga attacked and killed everyone except Drulzegar. Since then revenge is all Drulzegar thinks about, and the guilt is too much to bear.",sp=0},{t="Fry the Naga",b="Drulzegar wants seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses slain. A bad knee keeps Drulzegar from going along. The naga, Drulzegar says, usually lurk far down among the coral reefs beneath the waves, and the effort will be rewarded.",sp=0}},faq={{q="Who is Drulzegar Skraghook?",a="A fisherman at Shadowprey Village in Desolace. The naga killed the whole crew near Ranazjar Isle, and Drulzegar is the only survivor.",al={"drulzegar","drulzegar skraghook","who gives other fish to fry"}},{q="Where did the attack on Drulzegar's crew happen?",a="Beside Ranazjar Isle, north of a wreck on the coast. The crew fished there often, and the naga attacked one morning.",al={"where were the fishermen attacked","crew attack location","ranazjar isle ambush"}},{q="Why doesn't Drulzegar fight the naga himself?",a="Drulzegar has a bad knee, and says that without it they would help you kill the naga. The guilt over the crew weighs on Drulzegar's conscience.",al={"why cant drulzegar fight","drulzegar bad knee"}},{q="Where do the Slitherblade naga lurk?",a="Drulzegar says they usually lurk far down among the coral reefs beneath the waves. The attack on the crew happened near Ranazjar Isle.",al={"slitherblade location","where to find slitherblade naga","naga location desolace"}},{q="Which naga does Drulzegar want eliminated?",a="Seven Slitherblade Myrmidons, seven Slitherblade Naga and five Slitherblade Sorceresses.",al={"what naga need to be killed","other fish to fry targets","slitherblade requirements"}}},kw={"desolace","drulzegar","myrmidon","naga","other fish to fry","ranazjar isle","shadowprey village","skraghook","slitherblade","sorceress"},rel={"zone:desolace","topic:naga"},m={start="Drulzegar Skraghook",["end"]="Drulzegar Skraghook",level="36",faction="Horde",id=6143},src={"Other Fish to Fry"}}
E["quest:6161"] = {t="quest",n="Claim Rackmore's Treasure!",z="desolace",s="Rackmore's log tells of a ship bound for Feathermoon Stronghold that was set upon by creatures of the sea. To keep his treasure from his enemies, Rackmore hid the chest on Ranazjar Isle, and the silver key and golden key that open it are lost.",h="Rackmore's log tells of a ship bound for Feathermoon Stronghold that was set upon by creatures of the sea.",sec={{t="A Hidden Chest",b="The log says Rackmore's ship was on its way to Feathermoon Stronghold when seafaring creatures attacked it. Hoping to keep his treasure from his enemies, he hid the chest on Ranazjar Isle. Two keys open it, one silver and one gold, and both were lost. Someone who finds the keys and the chest will find a treasure.",sp=0}},faq={{q="Where was Rackmore's ship sailing when it was attacked?",a="His log says his ship was on its way to Feathermoon Stronghold when seafaring creatures attacked.",al={"rackmore destination","where was rackmore going","rackmore ship route"}},{q="Where is Rackmore's chest hidden?",a="On Ranazjar Isle, where Rackmore hid it.",al={"where is rackmore's chest","rackmore chest location","ranazjar isle chest"}},{q="What is needed to unlock the chest?",a="Two keys, Rackmore's Silver Key and Rackmore's Golden Key. Both were lost.",al={"rackmore chest keys","how to open rackmore's chest","what opens rackmore chest"}},{q="Why did Rackmore hide his treasure?",a="His ship came under attack, and he hid the chest on Ranazjar Isle so the treasure would not fall into enemy hands.",al={"why hide rackmore treasure","rackmore treasure motive"}}},kw={"chest","desolace","feathermoon stronghold","golden key","rackmore","ranazjar isle","silver key"},rel={"zone:desolace","subzone:feathermoon-stronghold"},m={start="Rackmore's Log",["end"]="Rackmore's Chest",level="36",faction="Neutral",id=6161},src={"Claim Rackmore's Treasure!"}}
E["quest:6568"] = {t="quest",n="The Testament of Rexxar",z="desolace",s="Rexxar says that slipping past the Black Flight's defenses calls for an illusion. He knows a master illusionist, Myranda the Hag, who lives in the Western Plaguelands, and sends you to her with a message.",h="Rexxar says that slipping past the Black Flight's defenses calls for an illusion.",sec={{t="The Art of Illusion",b="Rexxar asks what you know of illusions, since an illusion is how you will get around the Black Flight's defenses. He names someone who may assist you in such deception: Myranda the Hag, a master illusionist driven out by the Lordaeron alliance, living in the Western Plaguelands. Rexxar says she has lent his kind a hand before, whenever she found a cause worthy. You carry his message to her.",sp=0},{t="A Visitor in Lordaeron",b="Myranda remarks that a member of the Horde is a rare sight in these parts of Lordaeron, and she asks what you have brought her.",sp=0},{t="Myranda's Answer",b="Myranda holds the note, pauses and smiles. She asks after Rexxar, then explains that the page was blank on purpose: it held its writer's thoughts and intentions, and she can see why he kept it from ink, since it would be dangerous had you been captured or killed. She agrees to help you, as she owes the Warchief a favor or two.",sp=1}},faq={{q="Who is Myranda the Hag?",a="Myranda the Hag is a master illusionist who was once of Lordaeron and was exiled by its alliance. She is found in the Western Plaguelands, at Sorrow Hill.",al={"who is myranda","myranda the hag lore","where is myranda"}},{q="Why must you seek out an illusionist?",a="Rexxar says an illusion is how you will get around the Black Flight's defenses, and he knows a master who may help.",al={"why disguise","why seek an illusionist","fooling the black dragonflight"}},{q="Where does Rexxar send you?",a="He sends you to the Western Plaguelands, to find Myranda the Hag at Sorrow Hill.",al={"where do I go","where is sorrow hill","mistress of deception destination"}},{q="Has Myranda helped the Horde before?",a="Rexxar says she has helped his kind before, whenever she found the cause worthy.",al={"does myranda like the horde","myranda alliance or horde","myranda favor warchief"}}},kw={"black dragonflight","desolace","illusion","mistress of deception","myranda the hag","rexxar","sorrow hill","testament of rexxar","western plaguelands"},rel={"subzone:sorrow-hill","zone:westernplaguelands","zone:desolace","topic:black-dragonflight","topic:lordaeron","topic:horde"},m={start="Rexxar",["end"]="Myranda the Hag",level="60",faction="Horde",id=6568},src={"Mistress of Deception"}}
E["subzone:bolgan-s-hole"] = {t="subzone",n="Bolgan's Hole",z="desolace",s="Bolgan's Hole is a subterranean cavern nestled in the southern cliffs of Gelkis Village in Desolace. It serves as the inner sanctum of the Gelkis centaur clan, housing their highest chieftains and sacred earth relics.",h="Bolgan's Hole is a subterranean cavern nestled in the southern cliffs of Gelkis Village in Desolace.",sec={{t="The Gelkis Seat of Power",b="Carved deep into the craggy bluffs overlooking the Gelkis encampment, Bolgan's Hole functions as the command center for the tribe. It is here that the ruling khan holds court, surrounded by veteran guards and the tribe's most influential shamans. The cavern offers natural fortification against rival clans, most notably the bloodthirsty Magram centaur to the east.",sp=0},{t="Tears of the Earth Princess",b="Beyond its military importance, the cave possesses profound religious significance to the Gelkis. Luminous blue mineral formations known as the tears of Theradras sprout from the damp stone walls. Gelkis shamans obsessively harvest and guard these crystals, revering them as divine blessings that confer the subterranean protection of Princess Theradras, the primal earth elemental mother of the centaur race.",sp=0}},faq={{q="Where is Bolgan's Hole located?",a="Bolgan's Hole is a cave situated in the southern part of Gelkis Village, tucked into the hills of southern Desolace.",al={"bolgans hole location","where is bolgan's hole","bolgan cave entrance"}},{q="Who lives inside Bolgan's Hole?",a="The cave houses the high leadership of the Gelkis centaur, including their clan khan—such as Khan Shaka—as well as their inner circle of protectors and mystical shamans.",al={"who is in bolgan's hole","bolgans hole boss","gelkis khan location"}},{q="What are the glowing blue crystals inside the cave?",a="The crystals are known as the tears of Theradras. The Gelkis revere them as physical manifestations of their earth mother's favor, believing the stones grant mystical protection to those who possess them.",al={"blue crystals in bolgan's hole","tears of theradras","bolgan's hole rocks"}},{q="Can players enter Bolgan's Hole safely?",a="By default, the Gelkis centaur inside are aggressively hostile to outsiders. However, travelers who align themselves with the Gelkis by slaughtering their hated rivals, the Magram clan, can earn standing to walk the cave in peace.",al={"is bolgan's hole hostile","friendly to gelkis","can i go inside bolgans hole"}}},ang={["class:Shaman"]="The cavern offers a grim demonstration of how earth worship can be corrupted when tied to the violent legacy of Princess Theradras rather than the natural balance of the spirits."},kw={"bolgan's hole","centaur","desolace","gelkis","khan shaka","tears of theradras"},rel={"subzone:gelkis-village","topic:centaur","zone:desolace"},src={"Bolgan's Hole"}}
E["subzone:ethel-rethor"] = {t="subzone",n="Ethel Rethor",z="desolace",s="Ethel Rethor is an ancient night elven ruin situated along the rugged northwestern coast of Desolace. While a solitary, sealed tower still rises above the waves, the majority of the sunken settlement now lies submerged in the sea and overrun by hostile naga.",h="Ethel Rethor is an ancient night elven ruin situated along the rugged northwestern coast of Desolace.",sec={{t="A Drowned Relic",b="Perched on the desolate coast of western Kalimdor, Ethel Rethor stands as a haunting reminder of the ancient night elven civilization that flourished before the Great Sundering. Much of the grand architecture has collapsed into the ocean depths, leaving only shattered foundations and a lone, weathered tower protruding from the surf. A small bridge extends toward the tower's sealed portal, but the structure remains shut tight against the elements and intruders alike. The submerged chambers and surrounding shallows have become a stronghold for coastal naga, making the waters treacherous for any who wander near.",sp=0},{t="Watchers on the Shore",b="Despite its remote location and serpentine infestation, Ethel Rethor draws travelers interested in Kalimdor's forgotten histories and ongoing threats. An agent of the Argent Dawn, Azore Aldamort, maintains a watchful presence near the ruins, monitoring the naga menace and offering aid to intrepid adventurers willing to dive into the sunken passages. Between the aquatic dangers offshore and the barren wastes inland, the ruins serve as a lonely coastal crossroads.",sp=0}},faq={{q="What is Ethel Rethor?",a="Ethel Rethor is a ruined night elven coastal settlement in northwestern Desolace. Most of its former structures are now submerged beneath the sea, leaving behind a solitary offshore tower and drowned stonework.",al={"ethel rethor lore","what is this place desolace","ethel rethor ruin"}},{q="Who controls Ethel Rethor now?",a="The sunken ruins and adjacent reefs are occupied by naga. Like many ancient Kaldorei sites along the coast, the serpentine creatures have laid claim to the drowned halls and patrol the surrounding shallows aggressively.",al={"who lives in ethel rethor","ethel rethor monsters","naga at ethel rethor"}},{q="Can you go inside the tower?",a="The tower rising from the sea features a small bridge leading to an entrance, but the doorway remains firmly sealed shut. Travelers can only explore its exterior and dive into the sunken ruins beneath it.",al={"open ethel rethor tower","ethel rethor door","inside ethel rethor"}},{q="Why is the Argent Dawn here?",a="An Argent Dawn representative, Azore Aldamort, is stationed near the ruins. While the Dawn primarily focuses on the Scourge in the east, their operatives across Kalimdor monitor unusual magical disturbances, ancient ruins, and emerging threats like the naga.",al={"argent dawn in desolace","azore aldamor ethel rethor","argent dawn npc desolace"}}},ang={["race:NightElf"]="For night elves, Ethel Rethor is a somber monument to their lost empire, reminding them of the cataclysmic Sundering and the mutated brethren who now prowl the sunken halls.",["faction:Alliance"]="Alliance travelers moving through the hostile barrens of Desolace can find a rare neutral friendly face stationed near the ruins in the Argent Dawn observer Azore Aldamort."},kw={"argent dawn","azore aldamor","desolace","desolace coast","ethel rethor","kaldorei ruins","naga","sunken ruins"},rel={"zone:desolace","topic:naga","topic:argent-dawn","subzone:shadowprey-village"},src={"Ethel Rethor"}}
E["subzone:gelkis-village"] = {t="subzone",n="Gelkis Village",z="desolace",s="Gelkis Village is the primary stronghold of the earth-aligned Gelkis centaur clan in southwestern Desolace. Built around a rugged ravine connected by wooden spans and cliffside paths, the settlement guards the southern route toward Feralas. Its vantage directly overlooks the main north-south road, making it a perilous crossing for any traveler who has not earned the clan's favor.",h="Gelkis Village is the primary stronghold of the earth-aligned Gelkis centaur clan in southwestern Desolace.",sec={{t="A Fortress in the Ravine",b="Gelkis Village sits in a deep, craggy gorge framed by precarious bluffs and rope bridges. Unlike the nomadic raiders of the Barrens, the Gelkis have fortified their ancestral grounds into a permanent settlement, complete with outposts spreading toward the border of Feralas. The heart of the clan's leadership lies within Bolgan's Hole, a cavern carved into the southern cliff face where Khan Shaka oversees his warriors. Travelers trekking south through Desolace must either cut a bloody path through the gorge or tread carefully, as the Gelkis view uninvited wanderers as fair game in their eternal war against their rival centaur brethren.",sp=0}},faq={{q="Who lives in Gelkis Village?",a="The settlement belongs to the Gelkis clan, one of the warring centaur tribes of Desolace. They are staunch earth-worshipers ruled by Khan Shaka, who resides deep in the cliffside cave known as Bolgan's Hole.",al={"gelkis residents","who controls gelkis village","centaur village south"}},{q="Why are the Gelkis centaur hostile to outsiders?",a="Centaur culture is intensely territorial and aggressive toward outsiders. However, the Gelkis hate their rival clan, the Magram, above all else. Adventurers who actively hunt Magram warriors can eventually earn the Gelkis clan's trust and enter the village safely.",al={"why are gelkis attacking","gelkis hostile","can i be friendly with gelkis"}},{q="Where is Gelkis Village located?",a="It is located in southwestern Desolace, just east and slightly south of the troll settlement of Shadowprey Village. Its ravines border the southern mountain face and overlook the trail heading directly south into Feralas.",al={"gelkis location","how to find gelkis village","where is gelkis"}},{q="What is Bolgan's Hole?",a="Bolgan's Hole is a large cavern carved into the southern rock wall of the ravine, connected to the rest of the village via elevated bridges and bluffs. It serves as the inner sanctuary and seat of power for the Gelkis Khan.",al={"bolgans hole","cave in gelkis village","where is gelkis khan"}}},ang={["race:Tauren"]="Centaur drove the tauren from their ancestral lands for generations; seeing the Gelkis fortified in their rocky bastions is a bitter reminder of their enduring threat to Kalimdor.",["faction:Horde"]="With the Darkspear settlement of Shadowprey Village resting directly to the west on the coast, the fortified presence of the Gelkis poses an ongoing threat to nearby Horde operations."},kw={"bolgan's hole","centaur","desolace","feralas","gelkis","khan shaka","magram","shadowprey"},rel={"subzone:bolgan-s-hole","zone:desolace","topic:centaur","subzone:shadowprey-village","zone:feralas"},src={"Gelkis Village"}}
E["subzone:ghost-walker-post"] = {t="subzone",n="Ghost Walker Post",z="desolace",s="Ghost Walker Post is a modest tauren settlement situated in the heart of Desolace right beside the ancient Kodo Graveyard. Far more exposed to regional dangers than Shadowprey Village on the western coast, it serves as a frontline Horde staging ground against centaur clans and the Burning Blade.",h="Ghost Walker Post is a modest tauren settlement situated in the heart of Desolace right beside the ancient...",sec={{t="A Watch on the Wastes",b="Perched on the dusty flats of central Desolace, Ghost Walker Post provides the Horde with an austere foothold in a hostile territory. Unlike the sheltered coastal fishing haven of Shadowprey Village, this post directly faces roaming centaur marauders and demon-worshiping cultists of the Burning Blade. Facilities are spartan, offering only the bare essentials for travelers, with no inn or flight master in sight. Despite the harsh conditions, a garrison of tauren and an orcish detachment sent by Warchief Thrall keep vigilant watch over the badlands.",sp=0},{t="Guardians of the Graveyard",b="Led by the tauren shaman Gurda Wildmane, the spiritual heart of the outpost is closely entwined with the neighboring Kodo Graveyard. Shamans stationed here tend to the dying beasts that wander in to perish, helping ease them into the next life and communing with their lingering spirits. Between spiritual communion and constant military readiness, the defenders of the post honor the ancient bond between the tauren and the mighty kodo amid the ashes of Desolace.",sp=0}},faq={{q="What is Ghost Walker Post?",a="It is a small, rugged Horde outpost located in central Desolace, established primarily by tauren with support from an orcish garrison.",al={"ghost walker post info","what is this camp","horde camp desolace"}},{q="Who leads Ghost Walker Post?",a="The post is led by Gurda Wildmane, a tauren shaman who tends to the camp's defenses and the neighboring Kodo Graveyard.",al={"who is in charge","ghost walker leader","gurda wildmane"}},{q="Why is the post located near the Kodo Graveyard?",a="Gurda Wildmane and fellow tauren shamans reside here to help ease dying kodo into their next lives and to commune with the spirits of the fallen beasts.",al={"why by kodo graveyard","kodo spirits camp","shaman kodo graveyard"}},{q="What enemies does Ghost Walker Post fight?",a="The garrison wages constant war against the local hostile centaur tribes and the sinister forces of the Burning Blade operating across Desolace.",al={"ghost walker enemies","who attacks ghost walker post","post threats"}},{q="Can I get a flight path or rest at an inn here?",a="No. The outpost provides only the bare necessities for adventurers and lacks both an innkeeper and a wind rider master. Travelers must seek transport elsewhere, such as Shadowprey Village.",al={"flight master ghost walker","innkeeper ghost walker","fp here?"}},{q="How does it compare to Shadowprey Village?",a="While Shadowprey Village is a protected troll enclave on the western coast, Ghost Walker Post is inland, heavily exposed to surrounding threats, and focused on frontier defense and spiritual duties.",al={"shadowprey vs ghost walker","other horde camp desolace"}}},ang={["race:Tauren"]="The camp reflects the tauren's deep sacred duty to the natural world, standing as guardians beside the ancestral resting grounds of the kodo.",["class:Shaman"]="Under Gurda Wildmane, the shamans here perform the sacred work of speaking with ancient spirits and easing dying beasts into the spirit world."},kw={"burning blade","centaur","desolace","ghost walker post","gurda wildmane","horde","kodo graveyard","shadowprey village","tauren","thrall"},rel={"zone:desolace","subzone:kodo-graveyard","subzone:shadowprey-village","topic:tauren","topic:horde","topic:centaur","npc:thrall","quest:4767"},src={"Ghost Walker Post"}}
E["subzone:kodo-graveyard"] = {t="subzone",n="Kodo Graveyard",z="desolace",s="The Kodo Graveyard is a sprawling expanse in central Desolace littered with the massive, bleached remains of ancient beasts. By instinct or tradition, aging and dying kodos make a final pilgrimage to this desolate hollow to collapse among the ribs of their ancestors.",h="The Kodo Graveyard is a sprawling expanse in central Desolace littered with the massive, bleached remains of...",sec={{t="Resting Place of Titans",b="Sprawling across the grey earth of Desolace, the Kodo Graveyard holds the colossal skeletons of ancient beasts, some far larger than any living kodo seen today. Dying kodos wander here to spend their final breaths among centuries of accumulated remains. This sacred peace is fragile: scavengers prowl the perimeter, and those who disturb the calcified ribs and skulls risk stirring furious kodo spirits from the dust.",sp=0},{t="A Land of Spirits",b="The boundary between the living and the dead wears exceptionally thin across the bone fields. Travelers who peer into the spirit realm find restless, towering kodo apparitions wandering silently among the dust storms. Nearby, the Horde maintains Ghost Walker Post, watching over the sacred grounds and keeping a wary eye on the wandering herds and spectral manifestations that linger around the bones.",sp=0}},faq={{q="Why do the kodos come here to die?",a="It is an instinctive ritual. When kodos grow ancient, sick, or near death, an innate compulsion drives them across the waste to lie down among the skeletons of their ancestors in this specific corner of Desolace.",al={"why are there bones here","kodo dying grounds","why do kodos gather here"}},{q="Why are some of the skeletons so enormous?",a="Some of the skeletons are much larger than the living kodos seen nearby. Their exact age and origins are not established.",al={"giant kodo bones","huge kodo ribs","massive bones desolace"}},{q="What happens if someone disturbs the bones?",a="Disturbing the remains often provokes the spirits of the dead. Vengeful kodo apparitions readily materialize to attack anyone attempting to scavenge or desecrate the resting place.",al={"looting kodo bones","kodo ghosts","bone collector quest"}},{q="What is Ghost Walker Post?",a="Ghost Walker Post is a small Horde encampment stationed right by the bone fields, allowing Horde travelers to rest, watch over the region's spiritual activity, and guide wanderers through central Desolace.",al={"horde camp near bones","ghost walker camp"}}},ang={["race:Tauren"]="The kodo is a revered partner and spiritual companion to the tauren, making the desecration of these ancestral resting grounds a grave matter.",["profession:Herbalism"]="The decaying remains and spiritual resonance of the graveyard make the area around the large skeletons fertile ground for gathering Grave Moss."},kw={"desolace","ghost walker post","grave moss","kodo bones","kodo graveyard","kodo spirits"},rel={"zone:desolace","subzone:ghost-walker-post","topic:horde"},src={"Kodo Graveyard"}}
E["subzone:kormek-s-hut"] = {t="subzone",n="Kormek's Hut",z="desolace",s="Kormek's Hut is a remote, ramshackle dwelling sitting amid the barren flats of north-central Desolace. Despite its desolate surroundings and mysterious namesake, it currently shelters an eccentric pair: an oddly peaceful cultist and a goblin obsessed with harvesting kodo bones.",h="Kormek's Hut is a remote, ramshackle dwelling sitting amid the barren flats of north-central Desolace.",sec={{t="A Strange Oasis of Oddities",b="Perched out in the arid wastes of north-central Desolace, this small hovel is named after a figure whose whereabouts and identity remain completely unknown. Instead of Kormek, travelers stumbling upon the hut encounter an unusual pairing living out in the middle of nowhere: Willow and Bibbly F'utzbuckle. Inside the hut sits Willow, a member of the otherwise hostile and nihilistic Twilight's Hammer who curiously treats outsiders with calm hospitality. Outside, a pen littered with sun-bleached kodo bones serves as the personal dance floor and staging ground for Bibbly, an excitable goblin captivated by the commercial potential of bone scavenging.",sp=0}},faq={{q="Who is Kormek?",a="No one knows. The hut bears Kormek's name, but neither the goblin outside nor the cultist inside explains who Kormek was, and the namesake is nowhere to be found in the wastes.",al={"who is kormek","kormek identity","where is kormek"}},{q="Why is there a friendly Twilight's Hammer cultist here?",a="Willow resides inside the hut and belongs to the Twilight's Hammer, a cult typically hostile to all mortal life. For reasons of her own, she remains non-aggressive toward travelers who drop by the remote shelter.",al={"willow twilights hammer","why is willow friendly","willow hut"}},{q="What is the goblin outside doing?",a="Bibbly F'utzbuckle spends his days excitedly dancing around an enclosure filled with kodo bones. Like many enterprising goblins, he is thrilled by the prospect of turning ancient desert remains into pure profit.",al={"bibbly futzbuckle","goblin dancing desolace","why is the goblin dancing"}},{q="Where is Kormek's Hut located?",a="The hut lies in north-central Desolace, situated in the dry, windswept flats north of the central crossroads and cemetery grounds.",al={"kormek hut location","where is kormek hut","kormek desolace"}}},kw={"bibbly f'utzbuckle","desolace","kodo bones","kormek","kormek's hut","twilight's hammer","willow"},rel={"zone:desolace","topic:twilight-s-hammer"},src={"Kormek's Hut"}}
E["subzone:magram-village"] = {t="subzone",n="Magram Village",z="desolace",s="Magram Village is the settlement of the Magram centaur clan, situated among foul yellow pools in southeastern Desolace. It serves as the primary base for the Magram as they wage relentless war against their hated rivals, the Gelkis.",h="Magram Village is the settlement of the Magram centaur clan, situated among foul yellow pools in southeastern...",sec={{t="A Stronghold in the Mire",b="Sprawled across islands and shores around stagnant, sulfurous pools in southeast Desolace, Magram Village is a rugged settlement cobbled together with crude wooden bridges and hide tents. The Magram centaur dwell here in constant vigilance against neighboring clans. Known for their sheer brutality and deep-seated animosity toward the southern Gelkis clan, the Magram are willing to tolerate outsiders only if those travelers prove their worth by slaughtering their Gelkis enemies.",sp=0}},faq={{q="Who lives in Magram Village?",a="The village is home to the Magram clan, one of several warring centaur tribes native to Desolace. They live under crude hide canopies on islands connected by rough footbridges.",al={"who is here","magram residents","centaur village"}},{q="Can I enter Magram Village without being attacked?",a="Initially, the Magram centaur are hostile to all outsiders. However, travelers can earn their trust by hunting down and killing their sworn enemies, the Gelkis centaur, to raise standing with the clan.",al={"are magram friendly","magram hostile","how to visit magram village"}},{q="Why are the pools around the village yellow?",a="The pools in and around the village are tainted with sulfur and mineral runoff typical of the barren wastes of Desolace, leaving them stagnant, discolored, and polluted.",al={"yellow water","polluted pools","magram water"}},{q="Why are the Magram fighting the Gelkis?",a="The centaur clans of Desolace share a legendary, bloodthirsty rivalry. The Magram and Gelkis clans in particular have waged a bitter war for dominance over the southern reaches of the wasteland for generations.",al={"magram vs gelkis","centaur blood feud","centaur war"}}},ang={["race:Tauren"]="Centaur savagery has plagued the tribes of Kalimdor for generations, making any settlement of these nomadic marauders an unsettling reminder of past bloodshed."},kw={"centaur","desolace","gelkis","magram","magram village","pools"},rel={"topic:centaur","zone:desolace"},src={"Magram Village"}}
E["subzone:mannoroc-coven"] = {t="subzone",n="Mannoroc Coven",z="desolace",s="Mannoroc Coven is a demon-infested ruin in southern Desolace, named after the pit lord Mannoroth. Settled among ancient night elf architecture, it stands as the largest stronghold of the Burning Legion in central Kalimdor. Cultists of the Burning Blade maintain active summoning portals here, filling the ash-choked land with felhounds, succubi, and infernals.",h="Mannoroc Coven is a demon-infested ruin in southern Desolace, named after the pit lord Mannoroth.",sec={{t="A Bastion of Fel Fire",b="Situated south of Ghost Walker Post and east of Shadowprey Village, Mannoroc Coven blankets the ancient night elf ruins in an oppressive, fel-tainted pall. The coven is commanded on the ground by Lord Azrethoc, alongside the Burning Blade warlock Jugkar Grim'rod. Together, they harness active summoning portals to pull demonic reinforcements straight into Kalimdor, including doomguards, infernals, and felhounds. Even as Horde-aligned travelers attempt to sever these links using relics like the Hand of Iruxos, new rifts continue to tear open through the scarred earth.",sp=1,bt={"q1480.4"}}},faq={{q="Why is this place called Mannoroc Coven?",a="The encampment takes its name in homage to Mannoroth the Destructor, the infamous pit lord who subjugated the orcs through the blood curse and perished in Ashenvale.",al={"who is mannoroc","mannoroc name origin","why named mannoroc"}},{q="Who rules over the coven?",a="Demonic forces here are led by the demon Lord Azrethoc. Mortal interests are directed by Jugkar Grim'rod, a warlock representing the Burning Blade cult.",al={"who leads mannoroc coven","mannoroc coven boss","azrethoc"},sp=1,bt={"q1480.4"}},{q="What ruins was the coven built upon?",a="The demonic encampment occupies the crumbling stone foundations of an ancient night elf settlement, long ruined even before the demons flooded the region with fel magic.",al={"what ruins are here","mannoroc ancient ruins","elf ruins desolace"}},{q="How are the demons arriving in Desolace?",a="Burning Blade cultists maintain magical summoning portals across the ruins. These portals draw continuous reinforcements directly from the Twisting Nether, frustrating outside attempts to permanently cleanse the site.",al={"where do demons come from","burning blade portals desolace"}}},ang={["class:Warlock"]="The concentrated fel energy and active Legion summoning rifts make the coven an object of keen tactical interest, offering firsthand observation of raw demonic manifestation.",["race:NightElf"]="Seeing the stonework of your ancient ancestors desecrated and trampled by demonic invaders makes Mannoroc Coven an agonizing reminder of the War of the Ancients."},kw={"azrethoc","burning blade","coven","desolace","felhounds","infernals","jugkar grim'rod","mannoroc"},rel={"zone:desolace","topic:burning-legion","subzone:ghost-walker-post","subzone:shadowprey-village","npc:taiga-wisemane","topic:night-elf"},src={"Mannoroc Coven"}}
E["subzone:nijel-s-point"] = {t="subzone",n="Nijel's Point",z="desolace",s="Nijel's Point is a fortified Alliance and Cenarion Circle redoubt perched high on the northern bluffs of Desolace. Tucked safely away from the blighted valleys below, it serves as the sole safe haven for Alliance travelers, researchers, and soldiers navigating the harsh wasteland.",h="Nijel's Point is a fortified Alliance and Cenarion Circle redoubt perched high on the northern bluffs of...",sec={{t="A Bastion Above the Wastes",b="Carved into the sheer cliffs bordering the Stonetalon Mountains, Nijel's Point stands well above the gray dust and marauding centaur packs of Desolace. The settlement is held by a detachment of the Stormwind Army under Captain Pentigast, charged with monitoring the violent clan wars that threaten Alliance interests across southern Kalimdor. Its high elevation and narrow access trails make it readily defensible, providing a secure staging ground for couriers, scouts, and griffin riders travelling between Stonetalon Peak, Theramore, and Feathermoon Stronghold.",sp=0},{t="Cenarion and Crusade Expeditions",b="Beyond the Stormwind garrison, the outpost shelters emissaries with distinct and perilous agendas. Keeper Marandis and his dryads use the camp as an operational base to confront Princess Theradras deep within Maraudon, seeking to recover the fallen demigod Zaetar. Even the Scarlet Crusade maintains an emissary here in Brother Anton, who seeks to scour the undead ravaging the valley floor. Despite the bustling presence of soldiers and druids, the identity of Nijel himself remains an ancient mystery lost even to those garrisoned atop the ridge.",sp=0}},faq={{q="Why is the Alliance stationed in Desolace?",a="Captain Pentigast leads a Stormwind Army detachment to monitor the warring centaur clans. The Alliance fears that once one clan wipes out the others, the victorious horde will turn its aggression toward neighboring territories and settlements like Stonetalon and Feralas.",al={"why is alliance here","stormwind army in desolace","why nijels point exists"}},{q="Who was Nijel?",a="Nobody at the outpost seems to know. His true history has been lost to time.",al={"who is nijel","nijel lore","who was nijels point named after"}},{q="What is the Cenarion Circle doing at Nijel's Point?",a="Keeper Marandis and his dryad sisters have come to Desolace to purge Maraudon, slay Princess Theradras, and reclaim the remains of Zaetar to return them to the sacred groves of the Stonetalon Mountains.",al={"druids in nijels point","keeper marandis mission","why are dryads here"}},{q="Why is the Scarlet Crusade at Nijel's Point?",a="Brother Anton serves as a distant emissary of the Scarlet Crusade. Brother Crowley in Stormwind sends Alliance adventurers to him, and he tests their resolve against the undead ravagers in Desolace's Valley of Bones.",al={"brother anton scarlet crusade","scarlet crusade in desolace"}}},ang={["faction:Alliance"]="Nijel's Point is your sole fortified refuge and flight staging ground in Desolace, linking supply lines between Stonetalon, Theramore, and Feralas.",["class:Druid"]="Keeper Marandis uses this high mountain sanctuary to organize the reclamation of Zaetar's remains from the corruption festering inside Maraudon."},kw={"brother anton","centaur","desolace","marandis","maraudon","nijel's point","outpost","pentigast"},rel={"zone:desolace","topic:stormwind-army","topic:cenarion-circle","topic:centaur","zone:stonetalon","subzone:feathermoon-stronghold","subzone:theramore-isle","topic:scarlet-crusade"},src={"Nijel's Point"}}
E["subzone:sar-theris-strand"] = {t="subzone",n="Sar'theris Strand",z="desolace",s="Sar'theris Strand forms the western coastline of Desolace, fronting the Veiled Sea. In stark contrast to the barren, grey inland wastes, the shore is sunny and grassy, though it remains perilous due to prowling naga, sea giants, and makrura.",h="Sar'theris Strand forms the western coastline of Desolace, fronting the Veiled Sea.",sec={{t="A Green Edge on a Grey Waste",b="Running the length of western Desolace, Sar'theris Strand offers a bizarre respite from the ash and dust of the inland plains. Here, the clifftops and beaches are bright and green. Yet the strand is far from welcoming: serpentine naga patrol the surf alongside towering sea giants and territorial makrura. Shipwrecks litter the shoals, including the ruined Karnitol vessel to the north and small shattered skiffs beneath the towers of Ethel Rethor, proving the sea is as treacherous as the shore.",sp=0},{t="Wreckage and Rare Waters",b="Beyond the constant threat of naga and giants, the waters off the strand are known among seasoned travelers for their peculiar bounties. The jagged coastal shallows conceal salvage from lost expeditions and merchant ventures, while the deep surf is home to rare marine wildlife, notably the prized Sar'theris Striker fish sought out by master fishermen across Kalimdor.",sp=0}},faq={{q="Why is Sar'theris Strand green when the rest of Desolace is dead?",a="The coastline is sunny and grassy in contrast to the barren, grey interior of Desolace. The source does not explain why this contrast persists.",al={"why green coast","desolace coastline grassy","sar'theris weather"}},{q="What creatures inhabit Sar'theris Strand?",a="The strand is dominated by the amphibious Slitherblade naga, wandering sea giants, and scuttling makrura. Travelers must constantly watch the surf, as patrols roam close to the water's edge.",al={"who lives here","sar'theris mobs","what monsters are on the strand"}},{q="What shipwrecks lie along the shore?",a="The Karnitol Shipwreck sits off the northern waters of the strand, while smaller vessels lie smashed on the beach bluffs beneath the ruined elven towers of Ethel Rethor.",al={"karnitol shipwreck","sunken boats strand","beach wreckage"}},{q="Why do fishermen seek out Sar'theris Strand?",a="The coastal waters here are the exclusive home of the Sar'theris Striker, an elusive fish recognized by renowned angler Nat Pagle as one of the ultimate tests of fishing mastery.",al={"sar'theris striker","fishing coast desolace","nat pagle fish"}}},ang={["profession:Cooking"]="The strand's shores and surrounding waters offer rich marine game, including makrura and rare ocean fish, though cooking fires must be lit under the constant watch of prowling naga."},kw={"desolace","karnitol","makrura","sar'theris","strand","striker"},rel={"zone:desolace","subzone:ethel-rethor","topic:naga","npc:nat-pagle"},src={"Sar'theris Strand"}}
E["subzone:sargeron"] = {t="subzone",n="Sargeron",z="desolace",s="Sargeron is the crumbled ruin of an ancient night elf city located in northern Desolace. Shattered during the Great Sundering, its former temples of Elune have been defiled and claimed by the Hatefury satyrs, who renamed the grounds in tribute to their master, Sargeras.",h="Sargeron is the crumbled ruin of an ancient night elf city located in northern Desolace.",sec={{t="A Defiled Sanctuary",b="Before the War of the Ancients broke the continent, this settlement was a flourishing center of worship dedicated to Elune, housing sacred grounds such as Elune's Temple, Sanctuary, and Cathedral. Its true name is lost to antiquity. When the world shattered, the city collapsed into rubble, leaving behind sanctified relics like the Cup of Elune, Elune's Brazier, and Elune's Handmaiden. In the millennia since, corrupted Hatefury satyrs overran the stones, repurposing the sacred Kaldorei architecture into a stronghold honoring the titan Sargeras.",sp=0}},faq={{q="What was Sargeron called before the Sundering?",a="Its original night elven name has been lost to time. The current name, Sargeron, was given to the ruins by the Hatefury satyrs in homage to the fallen titan Sargeras.",al={"original name","sargeron original name","what was it called"}},{q="Who occupies Sargeron now?",a="The ruins are occupied by the Hatefury satyrs, corrupt demonic beings spawned during the War of the Ancients who actively desecrate the ancient elven sites.",al={"who lives here","sargeron mobs","enemies in sargeron"}},{q="What holy sites were originally located here?",a="The city held several major sites devoted to the Moon Goddess, including Elune's Temple, Elune's Sanctuary, and Elune's Cathedral, which once sheltered revered relics such as the Cup of Elune.",al={"elune temples","holy sites","what buildings were here"}},{q="Why is Sargeron significant to night elves?",a="It serves as a grim reminder of the War of the Ancients and the defilement of Kaldorei holy spaces by demonic forces, harboring ancient elven artifacts that risk being lost or corrupted.",al={"night elf lore sargeron","why do night elves care"}}},ang={["race:NightElf"]="The ruins are a painful sight for any Kaldorei, as sacred altars of Elune are openly defiled by demonic satyrs who mock the goddess in Sargeras's name.",["class:Priest"]="Priests of the Moon will recognize remnants of Elune's Cathedral and holy relics scattered across the broken stones, urging purification."},kw={"cup of elune","desolace","elune","hatefury","kaldorei","sargeras","sargeron","satyr"},rel={"zone:desolace","topic:satyr","topic:elune","topic:sargeras","topic:night-elf","topic:war-of-the-ancients"},src={"Sargeron"}}
E["subzone:shadowbreak-ravine"] = {t="subzone",n="Shadowbreak Ravine",z="desolace",s="Shadowbreak Ravine is a secluded mountain hollow tucked away in southeastern Desolace. Cloaked among jagged crags near Magram Village, this eerie ravine serves as a hidden redoubt for the demonic forces and mortal zealots of the Burning Blade.",h="Shadowbreak Ravine is a secluded mountain hollow tucked away in southeastern Desolace.",sec={{t="A Hidden Enclave of Fel",b="Tucked deep into the barren mountain ridges southeast of Magram Village, Shadowbreak Ravine provides the Burning Blade with a secluded staging ground away from the eyes of wandering centaur tribes. Amid strange, oversized mushrooms and grim ritual encampments, cultists labor alongside summoned demons. Here, dark practitioners invoke fel energies and tend heavy ritual chains, using the natural isolation of the ravine to marshal reinforcements and maintain a firm demonic foothold within the badlands of Desolace.",sp=0}},faq={{q="What is Shadowbreak Ravine?",a="Shadowbreak Ravine is a hidden mountain ravine situated in southeastern Desolace, just beyond Magram Village. It serves as a concealed camp and staging ground for demonic minions and cultists serving the Burning Blade.",al={"shadowbreak ravine info","what is this place","where is shadowbreak ravine"}},{q="Who occupies the ravine?",a="The ravine is occupied by cultists of the Burning Blade working directly alongside demons. They use the ravine's sheltered terrain to perform dark rituals and support their broader offensive across the region.",al={"who lives here","shadowbreak ravine mobs","enemies in shadowbreak ravine"}},{q="What features can be found inside the ravine?",a="The ravine contains dark ritual structures, massive iron chains, and prominent giant mushrooms that sprout amidst the fel-tainted encampments hidden within the mountain clefts.",al={"what is inside shadowbreak ravine","landmarks in shadowbreak ravine"}}},ang={["class:Warlock"]="The dark summoning circles and concentrated fel presence make this secretive canyon a clear testament to the reach of the Burning Blade's dark arts."},kw={"burning blade","cultists","demons","desolace","fel","shadowbreak ravine","magram village"},rel={"zone:desolace","subzone:magram-village","topic:centaur"},src={"Shadowbreak Ravine"}}
E["subzone:shadowprey-village"] = {t="subzone",n="Shadowprey Village",z="desolace",s="Shadowprey Village is a remote Horde fishing settlement built along the rocky southern coast of Sar'theris Strand in Desolace. Populated largely by Darkspear troll fishermen and supported by tauren service keepers, it acts as a critical coastal outpost and trade lifeline amidst a barren wasteland.",h="Shadowprey Village is a remote Horde fishing settlement built along the rocky southern coast of Sar'theris...",sec={{t="A Haven on the Strand",b="Tucked against the cliffs of southern Desolace, Shadowprey Village offers safe harbor in a region notorious for centaur clans and desolate wastes. The settlement is primarily an encampment of troll fishermen whose hauls sustain not only their own village but also inland outposts like Ghost Walker Post. Despite the rough shoreline, towering wooden piers reach out into the ocean, allowing local anglers to brave deep waters and dive for shellfish among the submerged wreckage dotting Sar'theris Strand.",sp=0},{t="Coastal Tribulations",b="Maintaining a frontier port in Desolace is fraught with danger. Beyond the inland threat of marauding centaur and the demon-summoning Burning Blade, the ocean itself tests the village's survival with rough shoals and hungry sea life. Tauren allies, including Taiga Wisemane and the keepers of the inn and wind rider roost, help shore up defenses and keep trade routes open across Kalimdor.",sp=0}},faq={{q="Why is Shadowprey Village important to the Horde?",a="Desolace is an inhospitable wasteland lacking natural resources. Shadowprey Village serves as the Horde's sole coastal port in the region, bringing in vital hauls of fish and shellfish to feed garrisons like Ghost Walker Post while offering a wind rider travel hub connected to Stonetalon, Thunder Bluff, and Feralas.",al={"shadowprey purpose","why is shadowprey here","shadowprey horde role"}},{q="Who leads Shadowprey Village?",a="The settlement has no recorded single chieftain. The village operates as a loose community of troll fishermen, while tauren residents like Taiga Wisemane help guard it against the Burning Blade cultists stirring in Desolace.",al={"shadowprey leader","who is in charge of shadowprey"}},{q="Why are there tauren running the services in a troll village?",a="Shadowprey began as an indigenous Darkspear fishing outpost, but its role as a regional supply hub attracted the Horde's broader logistical apparatus. Tauren oversee essential shared infrastructure, maintaining the inn, managing the stables, and directing the wind rider roost connecting the port to Mulgore and beyond.",al={"tauren in shadowprey","why tauren here","shadowprey tauren"}},{q="What threats are troubling the fishermen?",a="Aside from hostile inland centaur, the village must reckon with the Burning Blade, whose demon-summoning cultists hold Thunder Axe Fortress, as well as the rough waters and dangerous sea life of the coast.",al={"shadowprey problems","shadowprey threats"}}},ang={["race:Troll"]="Shadowprey is a rare haven of Darkspear coastal culture in central Kalimdor, showcasing the tribe's traditional mastery of spearfishing, diving, and coastal survival.",["faction:Horde"]="For Horde travelers trekking through Desolace, Shadowprey Village provides the only coastal rest stop, flight hub, and secure supply base south of the Kodo Graveyard."},kw={"desolace","sar'theris strand","shadowprey","shadowprey village","taiga wisemane","troll fishing"},rel={"zone:desolace","subzone:sar-theris-strand","subzone:ghost-walker-post","npc:taiga-wisemane","topic:troll","topic:tauren","topic:horde","zone:thunderbluff"},src={"Shadowprey Village"}}
E["subzone:thunder-axe-fortress"] = {t="subzone",n="Thunder Axe Fortress",z="desolace",s="Thunder Axe Fortress is a fortified compound in northwestern Desolace serving as a stronghold for the demonic Burning Blade cult. Within its stone barracks, watchtowers, and darkened caves, cultists perform dark rituals to summon demonic entities and store stolen artifacts of power. The cult remains an active threat to anyone traversing the desolate wastes.",h="Thunder Axe Fortress is a fortified compound in northwestern Desolace serving as a stronghold for the demonic...",sec={{t="A Bastion of the Burning Blade",b="Perched in northwestern Desolace, Thunder Axe Fortress serves as a heavily guarded redoubt for the Burning Blade. Composed of stone barracks, defensive watchtowers, and deep caverns, it allows the cult to maintain a fortified foothold far from the gaze of Kalimdor's major cities. Here, the cultists gather fel energies, summon lesser demons, and concoct schemes to bring far more dangerous entities into the world.",sp=0},{t="Stolen Relics and Dark Summonings",b="The cult stores the Hand of Iruxos at the fortress, a relic linked to the demonic portals of Mannoroc Coven. A Burning Blade seer also studies the stolen Sceptre of Light atop one of the watchtowers. Azore Aldamort asks travelers to recover the sceptre, which is rumored to have been taken from the naga.",sp=1}},faq={{q="Who controls Thunder Axe Fortress?",a="The fortress is held by the Burning Blade cult, an organization devoted to demonic power and the remnants of the Shadow Council. On the ground, the fortress and its operations are overseen by warlocks such as Tyranis Malem.",al={"who runs thunder axe fortress","who is in thunder axe fortress","thunder axe fortress boss"},sp=1,bt={"q5726.3"}},{q="What is the Sceptre of Light?",a="The Sceptre of Light is an ancient artifact said to be able to sink entire cities beneath the sea. Azore Aldamort asks travelers to retrieve it from a Burning Blade seer studying it atop one of the fortress's watchtowers.",al={"sceptre of light","scepter of light","stolen naga artifact"},sp=1},{q="How is this fortress connected to Mannoroc Coven?",a="The cultists at Thunder Axe Fortress hold an artifact known as the Hand of Iruxos. This relic was directly linked to the demon portals active at the Mannoroc Coven in southern Desolace, binding their demonic efforts across the zone.",al={"mannoroc coven connection","hand of iruxos"}}},ang={["class:Warlock"]="The Burning Blade's experiments at the fortress demonstrate the reckless bounds of demonology, from binding lesser fiends to forcing planar rifts for greater entities.",["faction:Alliance"]="Investigating Thunder Axe Fortress aligns with Argent Dawn efforts to secure dangerous artifacts like the Sceptre of Light before fel cultists turn them against the continent."},kw={"burning blade","desolace","hand of iruxos","kohor","sceptre of light","thunder axe fortress","tyranis malem"},rel={"zone:desolace","subzone:mannoroc-coven","topic:argent-dawn","topic:naga","topic:light"},src={"Thunder Axe Fortress"}}
E["subzone:valley-of-spears"] = {t="subzone",n="Valley of Spears",z="desolace",s="The Valley of Spears is a rugged canyon nestled in western Desolace, serving as the stronghold of the Maraudine centaur clan. Enclosed by steep cliffs and guarded passes, the valley leads directly to Maraudon, the sacred ancestral burial ground of all centaurkind.",h="The Valley of Spears is a rugged canyon nestled in western Desolace, serving as the stronghold of the...",sec={{t="Stronghold of the Maraudine",b="Carved into the rugged heights of western Desolace, the Valley of Spears is a stronghold of the Maraudine clan. Accessible on foot only through narrow, easily defended mountain passes from the south and east, this enclosed valley provides the centaur with a natural bastion. Travelers who venture past the rocky chokepoints face dense encampments of hostile nomads guarding the approach to their most revered holy site.",sp=0},{t="The Threshold of Maraudon",b="Tucked away at the southwestern end of the valley lies the entrance to Maraudon, the sacred cavern housing the tomb of Zaetar, father of the centaur, where Princess Theradras dwells. Because of this proximity, the Maraudine defend the canyon with zealous fury against rival clans and outside interlopers alike. Anyone foolish enough to stumble into the valley unawares—such as careless gnome cartographers or scouts—frequently ends up captured or slain.",sp=0}},faq={{q="Who controls the Valley of Spears?",a="The valley is the primary territory of the Maraudine clan, one of the warring centaur factions fighting for dominance in Desolace.",al={"who lives here","valley of spears centaur clan","maraudine base"}},{q="Where does the Valley of Spears lead?",a="At the southwestern extremity of the valley lies the entrance to Maraudon, the holy ancestral cavern and burial ground of the centaur race.",al={"how to get to maraudon","maraudon entrance","what is at the end of valley of spears"}},{q="How do you enter the valley?",a="The valley is surrounded by sheer mountain ridges and can only be entered on foot through narrow mountain defiles in the east and south.",al={"valley of spears entrance","how to get in","passes into valley of spears"}},{q="Is anyone trapped in the valley?",a="Yes, an unfortunate gnome named Melizza Brimbuzzle has been taken prisoner by the Maraudine centaur and is held within their camps.",al={"melizza brimbuzzle","captive in valley of spears","gnome prisoner"}}},ang={["race:Tauren"]="Centaur savagery has plagued the tribes of Kalimdor for generations; navigating this stronghold brings the tauren face-to-face with the heart of that ancient enmity.",["faction:Alliance"]="The Alliance keeps a cautious eye on the region, particularly after exploratory travelers like the gnome Melizza Brimbuzzle were captured by the hostile Maraudine clan."},kw={"centaur","desolace","maraudine","maraudon","melizza brimbuzzle","valley of spears"},rel={"zone:desolace","topic:centaur"},src={"Valley of Spears"}}
E["zone:desolace"] = {t="zone",n="Desolace",z="desolace",s="Desolace is a bleak, windswept desert on Kalimdor's western coast, defined by cracked gray earth, constant stormy skies, and the bones of fallen beasts. It is the ancestral cradle of the vicious centaur race and a contested wasteland scarred by ancient Highborne ruins, encroaching demonic cults, and bitter tribal warfare. Both the Horde and Alliance maintain precarious footholds amidst the dust, each seeking to carve out influence while warding off spreading corruption.",h="Desolace is a bleak, windswept desert on Kalimdor's western coast, defined by cracked gray earth, constant...",sec={{t="A Land Cursed and Broken",b="Desolace was not always a barren expanse of ash and yellowed pools. Legend holds that the land withered when the earth elemental Princess Theradras drained the surrounding life force to regenerate her form. Zaetar, son of Cenarius, came to her, but rather than subduing her, he took the princess as his mate. From their unnatural union sprang the first centaur. In shame and bloodthirsty wrath, the newborn race murdered their father and overran the plains, leaving behind the scarred wasteland known today.",sp=0},{t="Warring Hooves",b="The interior of Desolace echoes with the thunder of thousands of hooves as four splintered centaur tribes wage endless war against all interlopers and each other. The Kolkar roam the eastern cliffs, the Magram hold crude yurts around brackish sinkholes, the Gelkis dwell behind rope bridges in deep southern ravines, and the fanatical Maraudine defend the approach to Maraudon itself. Travelers venturing across the wastes frequently find themselves drawn into this ancient blood feud, forced to slaughter one tribe to gain safe passage and tenuous parley with another.",sp=0},{t="Cults and Shadowed Coasts",b="Beyond the warring centaur, darker perils fester along the borders. The Burning Blade cult operates freely out of Thunder Axe Fortress and Shadowbreak Ravine, summoning demons and satyrs that threaten to drown the region in fel fire. Along the stormy shoreline, naga creep onto the beaches of Ethel Rethor, while Darkspear trolls spear fish from the stilted platforms of Shadowprey Village. Tucked high in the northern crags, the Alliance watches from Nijel's Point, suspicious of the Horde's expansion and ever wary of the demonic taint spreading from Mannoroc Coven.",sp=0}},faq={{q="Why is Desolace such a dead wasteland?",a="Legend holds the land was once fertile. The earth elemental Princess Theradras consumed the vitality of the region to rebuild her physical form, and the birth and violent expansion of the centaur shortly after destroyed whatever plant life survived, leaving only gray dust and ash.",al={"why is desolace dead","desolace lore origin"}},{q="Where did the centaur come from?",a="The centaur are the offspring of Zaetar, son of the demigod Cenarius, and the elemental Princess Theradras. Disgusted and enraged by their own twisted appearance, the first khans slew their father immediately after birth and multiplied across the plains in a frenzy of brutality.",al={"centaur origin","who made the centaur","zaetar theradras"}},{q="Can I ally with the centaur tribes here?",a="Yes. Adventurers can earn reputation with either the Gelkis or the Magram tribe by slaying members of their rival clan. Gaining enough standing with one unlocks access to their village, tribal quests, and peace within their territory, though it makes the opposing tribe permanently hostile.",al={"centaur reputation","gelkis or magram","how to befriend centaur"}},{q="What is Maraudon?",a="Maraudon is the sacred ancestral burial ground of the centaur race, hidden deep within the twisting western cliffs of Desolace. It serves as both the tomb of Zaetar and the subterranean lair of Princess Theradras, who continues to channel dark elemental corruption through its cavernous halls.",al={"where is maraudon","maraudon dungeon","what lies under desolace"}},{q="Who is the wanderer roaming Desolace with a bear?",a="That is Rexxar, the Champion of the Horde, accompanied by his loyal bear companion Misha. The half-ogre wanderer patrols the dusty highways of Desolace and the Stonetalon Mountains, keeping a watchful eye on the wilderness and assisting those on vital Horde business.",al={"rexxar desolace","beastmaster in desolace","who is the orc with a bear"}},{q="Why are the Alliance and Horde fighting the Burning Blade here?",a="The Burning Blade cult has taken over strongholds like Thunder Axe Fortress to summon demons and bind felsteeds. The demons and satyrs it calls up threaten a region-wide demonic infestation, a danger both the Horde and the Alliance must answer.",al={"burning blade desolace","thunder axe fortress cultists","why are demons here"}}},ang={["race:Tauren"]="For the tauren, Desolace is sacred and tragic ground. It is the cradle of the centaur, whose scourge drove your people to the brink of extinction.",["class:Warlock"]="The arid plains and demonic sites like Mannoroc Coven draw dark practitioners seeking the secrets of felsteeds, majestic wild horses twisted into fire-breathing horrors through forbidden Shadow Council rites.",["class:Druid"]="Cenarion Circle druids view Desolace as a horrifying scar upon the natural order, where Zaetar met his tragic demise and elemental decay chokes the earth.",["faction:Alliance"]="Operating out of Nijel's Point, the Alliance monitors both the treacherous centaur tribes and the suspicious spread of Horde settlements like Shadowprey Village alongside demonic cults.",["faction:Horde"]="The Horde strives to secure the coastline at Shadowprey Village and protect the kodo herds at Ghost Walker Post, while fighting relentlessly to crush the Burning Blade and prove the modern Horde is free of demonic influence."},kw={"burning blade","centaur","desolace","gelkis","magram","maraudon","nijel's point","shadowprey village","theradras","zaetar"},rel={"subzone:nijel-s-point","subzone:shadowprey-village","subzone:kodo-graveyard","subzone:gelkis-village","subzone:magram-village","subzone:thunder-axe-fortress","subzone:mannoroc-coven","zone:stonetalon"},src={"Desolace (Classic)","Desolace"}}
